#!/usr/bin/env python3
"""
Evaluation + Output Agent (EOA)
Final autonomous agent in multi-agent AI build system
Assesses and evaluates entire system output for deployment readiness
"""

import json
import os
from typing import Dict, List, Any, Optional
from pathlib import Path


class SystemEvaluator:
    """Core evaluation engine for multi-agent system assessment"""

    def __init__(self):
        self.memory_dir = Path("./memory")
        self.required_files = [
            "vta_output.json",
            "tech_arch_output.json", 
            "frontend_output.json",
            "automation_output.json"
        ]

    def load_agent_outputs(self) -> Dict[str, Any]:
        """Load all agent outputs from memory directory"""
        outputs = {}
        missing_files = []

        for file_name in self.required_files:
            file_path = self.memory_dir / file_name
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    agent_key = file_name.replace('_output.json', '').replace('_', '')
                    outputs[agent_key] = json.load(f)
            except FileNotFoundError:
                missing_files.append(file_name)
                outputs[file_name.replace('_output.json', '').replace('_', '')] = None
            except json.JSONDecodeError as e:
                outputs[file_name.replace('_output.json', '').replace('_', '')] = {
                    "error": f"JSON decode error: {str(e)}"
                }

        outputs['_missing_files'] = missing_files
        return outputs

    def evaluate_vision_translation(self, vta_data: Optional[Dict]) -> Dict[str, Any]:
        """Evaluate Vision Translation Agent output"""
        if not vta_data:
            return {
                "progress_percent": 0,
                "flags": ["VTA output missing"],
                "missing_elements": ["Complete vision translation"],
                "score": 0
            }

        required_keys = ["vision_statement", "requirements", "success_metrics", "constraints"]
        present_keys = [k for k in required_keys if k in vta_data and vta_data[k]]

        flags = []
        missing_elements = []

        # Check for key data presence
        if "vision_statement" not in vta_data or not vta_data["vision_statement"]:
            flags.append("Missing vision statement")
            missing_elements.append("Vision statement")

        if "requirements" not in vta_data or not vta_data["requirements"]:
            flags.append("Missing requirements specification")
            missing_elements.append("Requirements specification")

        # Check logical cohesion
        if vta_data.get("requirements") and vta_data.get("vision_statement"):
            if len(str(vta_data["requirements"])) < 100:
                flags.append("Requirements seem too brief")

        # Check completeness
        progress_percent = (len(present_keys) / len(required_keys)) * 100

        return {
            "progress_percent": progress_percent,
            "flags": flags,
            "missing_elements": missing_elements,
            "score": min(progress_percent, 100)
        }

    def evaluate_technical_architecture(self, techarch_data: Optional[Dict]) -> Dict[str, Any]:
        """Evaluate Technical Architecture Agent output"""
        if not techarch_data:
            return {
                "progress_percent": 0,
                "flags": ["Technical architecture output missing"],
                "missing_elements": ["Complete technical architecture"],
                "score": 0
            }

        required_keys = ["architecture", "technology_stack", "deployment_plan", "scalability"]
        present_keys = [k for k in required_keys if k in techarch_data and techarch_data[k]]

        flags = []
        missing_elements = []

        # Check architecture completeness
        if "architecture" not in techarch_data:
            flags.append("Missing system architecture")
            missing_elements.append("System architecture")
        elif isinstance(techarch_data["architecture"], dict):
            arch = techarch_data["architecture"]
            if "backend" not in arch or "frontend" not in arch:
                flags.append("Incomplete architecture specification")

        # Check technology stack
        if "technology_stack" not in techarch_data:
            flags.append("Missing technology stack")
            missing_elements.append("Technology stack")

        # Check deployment considerations
        if "deployment_plan" not in techarch_data:
            flags.append("Missing deployment plan")
            missing_elements.append("Deployment strategy")

        progress_percent = (len(present_keys) / len(required_keys)) * 100

        return {
            "progress_percent": progress_percent,
            "flags": flags,
            "missing_elements": missing_elements,
            "score": min(progress_percent, 100)
        }

    def evaluate_frontend_structure(self, frontend_data: Optional[Dict]) -> Dict[str, Any]:
        """Evaluate Frontend Agent output"""
        if not frontend_data:
            return {
                "progress_percent": 0,
                "flags": ["Frontend output missing"],
                "missing_elements": ["Complete UI/UX structure"],
                "score": 0
            }

        required_keys = ["ui_structure", "components", "user_flows", "styling"]
        present_keys = [k for k in required_keys if k in frontend_data and frontend_data[k]]

        flags = []
        missing_elements = []

        # Check UI structure
        if "ui_structure" not in frontend_data:
            flags.append("Missing UI structure")
            missing_elements.append("UI structure definition")

        # Check components
        if "components" not in frontend_data:
            flags.append("Missing component specifications")
            missing_elements.append("Component definitions")
        elif isinstance(frontend_data["components"], list) and len(frontend_data["components"]) == 0:
            flags.append("Empty component list")

        # Check user flows
        if "user_flows" not in frontend_data:
            flags.append("Missing user flow definitions")
            missing_elements.append("User flow specifications")

        progress_percent = (len(present_keys) / len(required_keys)) * 100

        return {
            "progress_percent": progress_percent,
            "flags": flags,
            "missing_elements": missing_elements,
            "score": min(progress_percent, 100)
        }

    def evaluate_automation_ops(self, automation_data: Optional[Dict]) -> Dict[str, Any]:
        """Evaluate Automation & Operations Agent output"""
        if not automation_data:
            return {
                "progress_percent": 0,
                "flags": ["Automation output missing"],
                "missing_elements": ["Complete automation & ops setup"],
                "score": 0
            }

        required_keys = ["ci_cd", "monitoring", "testing", "infrastructure"]
        present_keys = [k for k in required_keys if k in automation_data and automation_data[k]]

        flags = []
        missing_elements = []

        # Check CI/CD setup
        if "ci_cd" not in automation_data:
            flags.append("Missing CI/CD configuration")
            missing_elements.append("CI/CD pipeline")

        # Check monitoring
        if "monitoring" not in automation_data:
            flags.append("Missing monitoring setup")
            missing_elements.append("Monitoring configuration")

        # Check testing strategy
        if "testing" not in automation_data:
            flags.append("Missing testing strategy")
            missing_elements.append("Testing framework")

        # Check infrastructure
        if "infrastructure" not in automation_data:
            flags.append("Missing infrastructure setup")
            missing_elements.append("Infrastructure configuration")

        progress_percent = (len(present_keys) / len(required_keys)) * 100

        return {
            "progress_percent": progress_percent,
            "flags": flags,
            "missing_elements": missing_elements,
            "score": min(progress_percent, 100)
        }

    def calculate_alignment_score(self, evaluations: Dict[str, Dict], outputs: Dict[str, Any]) -> int:
        """Calculate overall alignment score (0-100)"""
        domain_scores = []

        for domain, eval_data in evaluations.items():
            if isinstance(eval_data, dict) and "score" in eval_data:
                domain_scores.append(eval_data["score"])

        if not domain_scores:
            return 0

        # Weight the scores based on critical importance
        weights = {
            "vision_translation": 0.3,
            "technical_architecture": 0.3,
            "frontend_structure": 0.25,
            "automation_ops": 0.15
        }

        weighted_score = 0
        total_weight = 0

        for i, domain in enumerate(["vision_translation", "technical_architecture", "frontend_structure", "automation_ops"]):
            if i < len(domain_scores):
                weighted_score += domain_scores[i] * weights[domain]
                total_weight += weights[domain]

        if total_weight == 0:
            return 0

        return int(weighted_score / total_weight)

    def assess_risks(self, evaluations: Dict[str, Dict], outputs: Dict[str, Any]) -> List[str]:
        """Identify top 3 technical or structural risks"""
        risks = []

        # Check for missing critical components
        missing_files = outputs.get('_missing_files', [])
        if missing_files:
            risks.append(f"Missing agent outputs: {', '.join(missing_files)}")

        # Check for low completion rates
        low_completion_domains = []
        for domain, eval_data in evaluations.items():
            if isinstance(eval_data, dict) and eval_data.get("progress_percent", 0) < 50:
                low_completion_domains.append(domain.replace('_', ' ').title())

        if low_completion_domains:
            risks.append(f"Low completion in critical areas: {', '.join(low_completion_domains)}")

        # Check for architecture-frontend misalignment
        tech_arch = outputs.get("techarch")
        frontend = outputs.get("frontend") 
        if tech_arch and frontend:
            if "technology_stack" in tech_arch and "framework" not in str(tech_arch["technology_stack"]).lower():
                risks.append("Potential technology stack misalignment between architecture and frontend")

        # Check for missing deployment strategy
        automation = outputs.get("automation")
        if not automation or "deployment_plan" not in str(automation):
            risks.append("Incomplete deployment and operations strategy")

        # Check for missing monitoring/observability
        if automation and "monitoring" not in str(automation):
            risks.append("Lack of monitoring and observability setup")

        # Return top 3 risks
        return risks[:3]

    def generate_next_tasks(self, evaluations: Dict[str, Dict], outputs: Dict[str, Any]) -> List[str]:
        """Generate actionable recommendations for final implementation"""
        tasks = []

        # Collect all missing elements
        all_missing = []
        for domain, eval_data in evaluations.items():
            if isinstance(eval_data, dict):
                all_missing.extend(eval_data.get("missing_elements", []))

        # Generate tasks based on missing elements
        if "Vision statement" in all_missing:
            tasks.append("Complete vision statement and requirements gathering")

        if "System architecture" in all_missing:
            tasks.append("Finalize system architecture and component design")

        if "Technology stack" in all_missing:
            tasks.append("Select and validate technology stack choices")

        if "UI structure definition" in all_missing or "Component definitions" in all_missing:
            tasks.append("Complete frontend component library and UI structure")

        if "CI/CD pipeline" in all_missing:
            tasks.append("Set up continuous integration and deployment pipeline")

        if "Monitoring configuration" in all_missing:
            tasks.append("Implement monitoring, logging, and alerting systems")

        # Add integration tasks
        tasks.append("Conduct end-to-end integration testing")
        tasks.append("Perform security audit and penetration testing")
        tasks.append("Create deployment runbook and rollback procedures")
        tasks.append("Set up production environment and monitoring dashboards")

        return tasks[:8]  # Limit to most critical tasks


def run(task: dict) -> dict:
    """
    Main entry point for Evaluation + Output Agent

    Args:
        task: Dictionary containing evaluation parameters

    Returns:
        dict: Complete evaluation report
    """
    evaluator = SystemEvaluator()

    # Load all agent outputs
    outputs = evaluator.load_agent_outputs()

    # Evaluate each domain
    evaluations = {
        "vision_translation": evaluator.evaluate_vision_translation(outputs.get("vta")),
        "technical_architecture": evaluator.evaluate_technical_architecture(outputs.get("techarch")),
        "frontend_structure": evaluator.evaluate_frontend_structure(outputs.get("frontend")),
        "automation_ops": evaluator.evaluate_automation_ops(outputs.get("automation"))
    }

    # Generate comprehensive assessment
    alignment_score = evaluator.calculate_alignment_score(evaluations, outputs)
    risk_assessment = evaluator.assess_risks(evaluations, outputs)
    next_tasks = evaluator.generate_next_tasks(evaluations, outputs)

    # Compile progress report
    progress_report = {}
    for domain, eval_data in evaluations.items():
        progress_report[domain] = {
            "completion_percent": eval_data.get("progress_percent", 0),
            "flags": eval_data.get("flags", []),
            "missing_elements": eval_data.get("missing_elements", [])
        }

    # Create final evaluation report
    evaluation_report = {
        "timestamp": "2025-07-18T00:00:00Z",
        "system_status": "evaluated",
        "progress_report": progress_report,
        "alignment_score": alignment_score,
        "risk_assessment": risk_assessment,
        "next_tasks": next_tasks,
        "overall_readiness": "ready_for_implementation" if alignment_score >= 70 else "requires_additional_work",
        "evaluation_summary": {
            "total_agents_evaluated": len([k for k in outputs.keys() if k != '_missing_files']),
            "missing_outputs": outputs.get('_missing_files', []),
            "critical_issues": len([flag for eval_data in evaluations.values() 
                                  for flag in eval_data.get("flags", []) 
                                  if "missing" in flag.lower()]),
            "recommendation": "Proceed with implementation" if alignment_score >= 70 
                           else "Address critical gaps before deployment"
        }
    }

    # Save evaluation report
    os.makedirs(evaluator.memory_dir, exist_ok=True)
    output_path = evaluator.memory_dir / "evaluation_report.json"

    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(evaluation_report, f, indent=2, ensure_ascii=False)

    return evaluation_report


if __name__ == "__main__":
    # Example usage and testing
    test_task = {
        "evaluation_type": "system_assessment",
        "include_recommendations": True
    }

    result = run(test_task)
    print(f"Evaluation completed. Alignment score: {result['alignment_score']}/100")
    print(f"Overall readiness: {result['overall_readiness']}")
    print(f"Report saved to: ./memory/evaluation_report.json")

#!/usr/bin/env python3
"""
Automation + Ops Agent (AOA)
Generates automation tasks, integration plans, backend logic flows, and operational architecture.
"""

import json
import os
from typing import Dict, List, Any


def load_agent_outputs() -> Dict[str, Any]:
    """Load outputs from previous agents."""
    outputs = {}

    # Load VTA output
    vta_path = "./memory/vta_output.json"
    if os.path.exists(vta_path):
        with open(vta_path, 'r') as f:
            outputs['vta'] = json.load(f)
    else:
        outputs['vta'] = {}

    # Load Tech Architecture output
    tech_arch_path = "./memory/tech_arch_output.json"
    if os.path.exists(tech_arch_path):
        with open(tech_arch_path, 'r') as f:
            outputs['tech_arch'] = json.load(f)
    else:
        outputs['tech_arch'] = {}

    # Load Frontend output
    frontend_path = "./memory/frontend_output.json"
    if os.path.exists(frontend_path):
        with open(frontend_path, 'r') as f:
            outputs['frontend'] = json.load(f)
    else:
        outputs['frontend'] = {}

    return outputs


def extract_key_data(outputs: Dict[str, Any]) -> Dict[str, Any]:
    """Extract key components, milestones, and specifications from agent outputs."""
    extracted = {
        'key_components': [],
        'milestones': [],
        'suggested_stack': {},
        'component_specs': {},
        'workflows': [],
        'backend_needs': []
    }

    # Extract from VTA
    vta_data = outputs.get('vta', {})
    extracted['key_components'].extend(vta_data.get('key_features', []))
    extracted['milestones'].extend(vta_data.get('milestones', []))
    extracted['workflows'].extend(vta_data.get('user_workflows', []))

    # Extract from Tech Architecture
    tech_data = outputs.get('tech_arch', {})
    extracted['suggested_stack'] = tech_data.get('suggested_stack', {})
    extracted['component_specs'] = tech_data.get('component_specs', {})
    extracted['backend_needs'].extend(tech_data.get('backend_requirements', []))

    # Extract from Frontend
    frontend_data = outputs.get('frontend', {})
    frontend_components = frontend_data.get('component_structure', {})
    extracted['key_components'].extend(frontend_components.keys() if isinstance(frontend_components, dict) else [])

    return extracted


def generate_automation_tasks(extracted_data: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Generate automated tasks based on system components and workflows."""
    automation_tasks = []

    # Database maintenance tasks
    automation_tasks.extend([
        {
            "name": "database_backup",
            "type": "scheduled",
            "schedule": "0 2 * * *",  # Daily at 2 AM
            "description": "Automated database backup and archival",
            "priority": "critical",
            "failure_action": "alert_admin"
        },
        {
            "name": "database_cleanup",
            "type": "scheduled", 
            "schedule": "0 3 * * 0",  # Weekly on Sunday at 3 AM
            "description": "Clean up old logs, temporary data, and optimize tables",
            "priority": "medium",
            "failure_action": "log_and_retry"
        }
    ])

    # Security and monitoring tasks
    automation_tasks.extend([
        {
            "name": "security_scan",
            "type": "scheduled",
            "schedule": "0 1 * * *",  # Daily at 1 AM
            "description": "Automated security vulnerability scanning",
            "priority": "high",
            "failure_action": "alert_security_team"
        },
        {
            "name": "health_check",
            "type": "periodic",
            "interval": 300,  # Every 5 minutes
            "description": "System health monitoring and service availability checks",
            "priority": "critical",
            "failure_action": "auto_restart_services"
        },
        {
            "name": "log_analysis",
            "type": "scheduled",
            "schedule": "*/15 * * * *",  # Every 15 minutes
            "description": "Analyze logs for anomalies and performance issues",
            "priority": "medium",
            "failure_action": "escalate_if_critical"
        }
    ])

    # Data processing tasks based on workflows
    for workflow in extracted_data.get('workflows', []):
        if isinstance(workflow, dict) and workflow.get('automated', False):
            automation_tasks.append({
                "name": f"workflow_{workflow.get('name', 'unnamed').lower().replace(' ', '_')}",
                "type": "event_driven",
                "trigger": workflow.get('trigger', 'manual'),
                "description": f"Automated execution of {workflow.get('name', 'workflow')}",
                "priority": workflow.get('priority', 'medium'),
                "failure_action": "retry_with_delay"
            })

    # Performance optimization tasks
    automation_tasks.extend([
        {
            "name": "cache_warmup",
            "type": "scheduled",
            "schedule": "0 */6 * * *",  # Every 6 hours
            "description": "Preload frequently accessed data into cache",
            "priority": "low",
            "failure_action": "log_only"
        },
        {
            "name": "resource_optimization",
            "type": "scheduled",
            "schedule": "0 4 * * *",  # Daily at 4 AM
            "description": "Analyze and optimize resource usage patterns",
            "priority": "medium",
            "failure_action": "generate_report"
        }
    ])

    return automation_tasks


def generate_integration_plan(extracted_data: Dict[str, Any]) -> Dict[str, Any]:
