    # Payment integrations if commerce features detected
    has_commerce = any('payment' in str(comp).lower() or 'commerce' in str(comp).lower() 
                      for comp in extracted_data.get('key_components', []))

    if has_commerce:
        integrations["payments"].extend([
            {
                "service": "Stripe",
                "purpose": "Payment processing and subscription management",
                "priority": "critical",
                "configuration": {
                    "public_key": "env:STRIPE_PUBLIC_KEY",
                    "secret_key": "env:STRIPE_SECRET_KEY",
                    "webhook_secret": "env:STRIPE_WEBHOOK_SECRET"
                }
            },
            {
                "service": "PayPal",
                "purpose": "Alternative payment method",
                "priority": "medium",
                "configuration": {
                    "client_id": "env:PAYPAL_CLIENT_ID",
                    "client_secret": "env:PAYPAL_CLIENT_SECRET"
                }
            }
        ])

    # Communication integrations
    integrations["communication"].extend([
        {
            "service": "SendGrid",
