#!/usr/bin/env python3
"""
Frontend Experience Agent (FEA)
Generates complete frontend UX/UI blueprint based on prior planning from other agents.
Part of a 5-agent self-building AI system.
"""

import json
import os
from typing import Dict, List, Any


def run(task: Dict[str, Any]) -> Dict[str, Any]:
    """
    Main entry point for Frontend Experience Agent.

    Args:
        task: Dictionary containing task parameters

    Returns:
        Dictionary with frontend experience blueprint
    """
    print("🎨 Frontend Experience Agent starting...")

    # Load inputs from previous agents
    vta_data = _load_vta_output()
    tech_arch_data = _load_tech_arch_output()

    # Extract key information
    project_info = _extract_project_info(vta_data, tech_arch_data)

    # Generate frontend blueprint
    frontend_blueprint = _generate_frontend_blueprint(project_info, task)

    # Save output
    _save_frontend_output(frontend_blueprint)

    print("✅ Frontend Experience Agent completed successfully")
    return frontend_blueprint


def _load_vta_output() -> Dict[str, Any]:
    """Load Vision Translator Agent output."""
    vta_path = "./memory/vta_output.json"

    if not os.path.exists(vta_path):
        print(f"⚠️ Warning: {vta_path} not found, using defaults")
        return {
            "project_vision": "Default project vision",
            "core_features": ["Basic functionality"],
            "user_personas": ["General user"],
            "project_type": "web application"
        }

    try:
        with open(vta_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        print(f"📖 Loaded VTA output from {vta_path}")
        return data
    except Exception as e:
        print(f"❌ Error loading VTA output: {e}")
        return {}


def _load_tech_arch_output() -> Dict[str, Any]:
    """Load Technical Architect Agent output."""
    tech_arch_path = "./memory/tech_arch_output.json"

    if not os.path.exists(tech_arch_path):
        print(f"⚠️ Warning: {tech_arch_path} not found, using defaults")
        return {
            "project_name": "Default Project",
            "key_components": ["main", "utils"],
            "file_tree": {"src/": ["main.py"]},
            "tech_stack": {"frontend": "HTML/CSS/JS"}
        }

    try:
        with open(tech_arch_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        print(f"📖 Loaded Tech Arch output from {tech_arch_path}")
        return data
    except Exception as e:
        print(f"❌ Error loading Tech Arch output: {e}")
        return {}


def _extract_project_info(vta_data: Dict[str, Any], tech_arch_data: Dict[str, Any]) -> Dict[str, Any]:
    """Extract and combine relevant information from both agents."""
    return {
        "project_name": tech_arch_data.get("project_name", "Unnamed Project"),
        "key_components": tech_arch_data.get("key_components", []),
        "file_tree": tech_arch_data.get("file_tree", {}),
        "tech_stack": tech_arch_data.get("tech_stack", {}),
        "project_vision": vta_data.get("project_vision", ""),
        "core_features": vta_data.get("core_features", []),
        "user_personas": vta_data.get("user_personas", []),
        "project_type": vta_data.get("project_type", "web application")
    }


def _generate_frontend_blueprint(project_info: Dict[str, Any], task: Dict[str, Any]) -> Dict[str, Any]:
    """Generate comprehensive frontend experience blueprint."""

    # Determine application type and complexity
    app_type = _determine_app_type(project_info)
    complexity = _assess_complexity(project_info)

    # Generate each component of the blueprint
    page_map = _generate_page_map(project_info, app_type)
    component_list = _generate_component_list(project_info, complexity)
    layout_structure = _generate_layout_structure(project_info, app_type)
    ui_tone = _determine_ui_tone(project_info)
    style_framework = _select_style_framework(project_info, complexity)
    frontend_file_structure = _generate_frontend_file_structure(project_info, style_framework)

    return {
        "project_name": project_info["project_name"],
        "page_map": page_map,
        "component_list": component_list,
        "layout_structure": layout_structure,
        "ui_tone": ui_tone,
        "style_framework": style_framework,
        "frontend_file_structure": frontend_file_structure,
        "metadata": {
            "app_type": app_type,
            "complexity": complexity,
            "generated_by": "Frontend Experience Agent",
            "tech_stack": project_info["tech_stack"]
        }
    }


def _determine_app_type(project_info: Dict[str, Any]) -> str:
    """Determine the type of application based on project information."""
    project_type = project_info.get("project_type", "").lower()
    features = [f.lower() for f in project_info.get("core_features", [])]

    # Check for specific application types
    if any(keyword in project_type for keyword in ["dashboard", "admin", "analytics"]):
        return "dashboard"
    elif any(keyword in project_type for keyword in ["ecommerce", "shop", "store"]):
        return "ecommerce"
    elif any(keyword in project_type for keyword in ["blog", "content", "cms"]):
        return "content_management"
    elif any(keyword in project_type for keyword in ["social", "community", "chat"]):
        return "social_platform"
    elif any(keyword in project_type for keyword in ["landing", "marketing", "promotional"]):
        return "marketing_site"
    elif any(keyword in features for keyword in ["api", "data", "crud"]):
        return "data_application"
    else:
        return "web_application"


def _assess_complexity(project_info: Dict[str, Any]) -> str:
    """Assess the complexity level of the project."""
    features_count = len(project_info.get("core_features", []))
    components_count = len(project_info.get("key_components", []))

    total_score = features_count + components_count

    if total_score <= 3:
        return "simple"
    elif total_score <= 8:
        return "moderate"
    else:
        return "complex"


def _generate_page_map(project_info: Dict[str, Any], app_type: str) -> Dict[str, Any]:
