        "Card": "Display", "Modal": "Display", "Chart": "Display", "Calendar": "Display",
        "Sidebar": "Navigation",
        "NotificationBanner": "Feedback",
        "DataTable": "Data", "ChatMessage": "Data", "ProductCard": "Data"
    }

    for component_name in components.keys():
        category = category_mapping.get(component_name, "Display")
        categories[category].append(component_name)

    return categories


def _generate_layout_structure(project_info: Dict[str, Any], app_type: str) -> Dict[str, Any]:
    """Generate layout structure for different page types."""

    layouts = {
