                    "collapsible": True
                },
                "main": {
                    "flex": 1,
                    "contains": ["dashboard_widgets", "page_content"],
                    "padding": "16px"
                }
            }
        }

    if app_type in ["ecommerce", "content_management"]:
        layouts["grid"] = {
            "description": "Grid layout for product/content listings",
            "zones": {
                "header": {
                    "height": "64px",
