        "layouts": layouts,
        "responsive_breakpoints": {
            "mobile": "768px",
            "tablet": "1024px",
            "desktop": "1280px"
        }
    }


def _determine_ui_tone(project_info: Dict[str, Any]) -> Dict[str, Any]:
    """Determine the appropriate UI tone and style direction."""

    project_type = project_info.get("project_type", "").lower()
    features = [f.lower() for f in project_info.get("core_features", [])]

    # Determine primary tone
    if any(keyword in project_type for keyword in ["corporate", "enterprise", "business"]):
        tone = "professional"
    elif any(keyword in project_type for keyword in ["creative", "art", "design"]):
        tone = "creative"
    elif any(keyword in project_type for keyword in ["tech", "developer", "code"]):
        tone = "modern_tech"
    elif any(keyword in project_type for keyword in ["social", "community", "fun"]):
        tone = "friendly"
    else:
        tone = "clean_minimal"

    # Define tone characteristics
    tone_definitions = {
        "professional": {
            "primary_colors": ["blue", "navy", "gray"],
            "typography": "clean_serif",
            "spacing": "generous",
            "personality": "trustworthy, authoritative, polished"
        },
        "creative": {
            "primary_colors": ["purple", "orange", "teal"],
            "typography": "modern_sans",
            "spacing": "dynamic",
            "personality": "innovative, expressive, bold"
        },
        "modern_tech": {
            "primary_colors": ["dark", "blue", "green"],
            "typography": "monospace_accent",
            "spacing": "tight",
            "personality": "cutting-edge, precise, efficient"
        },
        "friendly": {
            "primary_colors": ["warm_blue", "orange", "green"],
            "typography": "rounded_sans",
            "spacing": "comfortable",
            "personality": "approachable, welcoming, energetic"
        },
        "clean_minimal": {
            "primary_colors": ["gray", "white", "accent"],
            "typography": "clean_sans",
            "spacing": "balanced",
            "personality": "simple, focused, elegant"
        }
    }

    return {
        "primary_tone": tone,
        "characteristics": tone_definitions[tone],
        "color_strategy": _generate_color_strategy(tone),
        "typography_strategy": _generate_typography_strategy(tone)
    }


def _generate_color_strategy(tone: str) -> Dict[str, str]:
    """Generate color strategy based on UI tone."""
    strategies = {
        "professional": {
            "primary": "#1e40af",
            "secondary": "#64748b", 
            "accent": "#f59e0b",
