    return strategies.get(tone, strategies["clean_minimal"])


def _generate_typography_strategy(tone: str) -> Dict[str, str]:
    """Generate typography strategy based on UI tone."""
    strategies = {
        "professional": {
            "heading_font": "serif",
            "body_font": "sans-serif",
            "accent_font": "sans-serif",
            "size_scale": "traditional"
        },
        "creative": {
