        }
    }

    return strategies.get(tone, strategies["clean_minimal"])


def _select_style_framework(project_info: Dict[str, Any], complexity: str) -> Dict[str, Any]:
    """Select the most appropriate CSS/styling framework."""

    tech_stack = project_info.get("tech_stack", {})
    frontend_tech = tech_stack.get("frontend", "").lower()

    # Determine framework based on project needs and complexity
    if "react" in frontend_tech and complexity == "complex":
        framework = "mantine"
        reason = "Rich component library ideal for complex React applications"
    elif "react" in frontend_tech:
        framework = "tailwind"
        reason = "Flexible utility-first CSS framework, great for React"
    elif complexity == "simple":
        framework = "raw_css"
        reason = "Simple project doesn't require framework overhead"
    elif "vue" in frontend_tech or "angular" in frontend_tech:
        framework = "material_ui"
        reason = "Mature design system with good framework support"
    else:
        framework = "tailwind"
        reason = "Versatile framework suitable for most projects"

    framework_details = {
        "tailwind": {
            "name": "Tailwind CSS",
            "type": "utility_first",
            "benefits": ["Highly customizable", "Small bundle size", "Fast development"],
            "setup_requirements": ["PostCSS configuration", "Build process integration"]
        },
        "mantine": {
            "name": "Mantine",
            "type": "component_library",
            "benefits": ["Rich component set", "Built-in theme system", "TypeScript support"],
            "setup_requirements": ["React 16.8+", "Emotion/styled-components"]
        },
        "material_ui": {
            "name": "Material-UI (MUI)",
            "type": "design_system",
            "benefits": ["Google Material Design", "Comprehensive components", "Accessibility built-in"],
            "setup_requirements": ["React 17+", "Emotion as styling engine"]
        },
        "raw_css": {
            "name": "Raw CSS",
            "type": "vanilla",
            "benefits": ["Full control", "No dependencies", "Lightweight"],
            "setup_requirements": ["CSS preprocessing (optional)", "Build tools for optimization"]
        }
    }

    return {
        "selected_framework": framework,
        "selection_reason": reason,
        "framework_details": framework_details[framework],
        "alternative_options": [k for k in framework_details.keys() if k != framework]
    }


def _generate_frontend_file_structure(project_info: Dict[str, Any], style_framework: Dict[str, Any]) -> Dict[str, Any]:
    """Generate frontend file and folder structure."""

    framework = style_framework["selected_framework"]
    tech_stack = project_info.get("tech_stack", {})

    # Base structure
    structure = {
        "src/": {
            "components/": {
                "ui/": ["Button.jsx", "Input.jsx", "Card.jsx", "Modal.jsx"],
                "layout/": ["Header.jsx", "Footer.jsx", "Sidebar.jsx"],
                "forms/": ["ContactForm.jsx", "LoginForm.jsx"]
            },
            "pages/": [],
            "hooks/": ["useApi.js", "useAuth.js"],
            "utils/": ["constants.js", "helpers.js", "api.js"],
            "styles/": []
        },
        "public/": {
            "images/": [],
            "icons/": [],
            "fonts/": []
        }
    }

    # Add pages based on page map
    structure["src/"]["pages/"] = [f"{page}.jsx" for page in ["Home", "About", "Contact"]]

    # Add framework-specific files
    if framework == "tailwind":
        structure["src/"]["styles/"] = ["globals.css", "tailwind.css", "components.css"]
        structure["tailwind.config.js"] = "Tailwind configuration"
        structure["postcss.config.js"] = "PostCSS configuration"

    elif framework == "mantine":
        structure["src/"]["theme/"] = ["index.js", "colors.js", "components.js"]
        structure["src/"]["styles/"] = ["globals.css"]

    elif framework == "material_ui":
        structure["src/"]["theme/"] = ["theme.js", "components.js"]
        structure["src/"]["styles/"] = ["globals.css", "mui-overrides.css"]

    else:  # raw_css
        structure["src/"]["styles/"] = [
            "main.css", "variables.css", "components.css", 
            "layouts.css", "utilities.css"
        ]

    # Add build configuration files
    root_files = ["package.json", "README.md", ".gitignore"]

    if "react" in tech_stack.get("frontend", "").lower():
        root_files.extend(["vite.config.js", "index.html"])

    return {
        "directory_structure": structure,
        "root_files": root_files,
        "total_estimated_files": _count_files_in_structure(structure) + len(root_files),
        "key_directories": list(structure.keys()),
        "organization_notes": [
            "Components organized by type and reusability",
            "Pages represent distinct application routes", 
            "Hooks directory for custom React hooks",
            "Utils for shared functionality and constants",
            "Styles organized by framework and purpose"
        ]
    }


def _count_files_in_structure(structure: Dict[str, Any]) -> int:
    """Recursively count files in the directory structure."""
    count = 0
    for key, value in structure.items():
        if isinstance(value, dict):
            count += _count_files_in_structure(value)
        elif isinstance(value, list):
            count += len(value)
        else:
            count += 1
    return count


def _save_frontend_output(frontend_blueprint: Dict[str, Any]) -> None:
    """Save frontend blueprint to memory file."""
    memory_dir = "./memory"

    # Ensure memory directory exists
    if not os.path.exists(memory_dir):
        os.makedirs(memory_dir)
        print(f"📁 Created memory directory: {memory_dir}")

    output_path = os.path.join(memory_dir, "frontend_output.json")

