#!/usr/bin/env python3
"""
Technical Architect Agent (TAA)

Generates technical blueprints and system architecture plans based on
project specifications from the Vision Translator Agent.
"""

import json
import os
import uuid
from datetime import datetime
from typing import Dict, List, Any, Optional


class TechnicalArchitectAgent:
    """
    Agent responsible for creating technical architecture blueprints
    from high-level project specifications.
    """

    def __init__(self):
        self.memory_dir = "./memory"
        self.output_file = "tech_arch_output.json"

    def _ensure_memory_directory(self) -> None:
        """Ensure the memory directory exists."""
        if not os.path.exists(self.memory_dir):
            os.makedirs(self.memory_dir)

    def _load_latest_vta_output(self) -> Optional[Dict[str, Any]]:
        """
        Load the most recent vta_output.json from memory directory.

        Returns:
            Dict containing VTA output or None if not found
        """
        vta_file = os.path.join(self.memory_dir, "vta_output.json")

        if not os.path.exists(vta_file):
            print(f"Warning: {vta_file} not found")
            return None

        try:
            with open(vta_file, 'r', encoding='utf-8') as f:
                return json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            print(f"Error loading VTA output: {e}")
            return None

    def _generate_file_structure(self, project_type: str, components: List[str], 
                               tech_stack: Dict[str, str]) -> Dict[str, Any]:
        """
        Generate a file structure plan based on project specifications.

        Args:
            project_type: Type of project (web_app, api, desktop_app, etc.)
            components: List of main components
            tech_stack: Dictionary of technology choices

        Returns:
            Dictionary containing file structure plan
        """
        base_structure = {
            "root": {
                "type": "directory",
                "files": ["README.md", "requirements.txt", ".gitignore"],
                "subdirectories": {}
            }
        }

        # Add project-specific structure based on type
        if project_type == "web_app":
            base_structure["root"]["subdirectories"].update({
                "frontend": {
                    "type": "directory",
                    "files": ["index.html", "package.json"],
                    "subdirectories": {
                        "src": {"type": "directory", "files": ["main.js", "App.js"]},
                        "assets": {"type": "directory", "files": ["styles.css"]},
                        "components": {"type": "directory", "files": []}
                    }
                },
                "backend": {
                    "type": "directory",
                    "files": ["app.py", "config.py"],
                    "subdirectories": {
                        "api": {"type": "directory", "files": ["routes.py"]},
                        "models": {"type": "directory", "files": ["database.py"]},
                        "utils": {"type": "directory", "files": ["helpers.py"]}
                    }
                }
            })
        elif project_type == "api":
            base_structure["root"]["subdirectories"].update({
                "src": {
                    "type": "directory",
                    "files": ["main.py", "config.py"],
                    "subdirectories": {
                        "routes": {"type": "directory", "files": ["__init__.py"]},
                        "models": {"type": "directory", "files": ["__init__.py"]},
                        "middleware": {"type": "directory", "files": ["__init__.py"]},
                        "utils": {"type": "directory", "files": ["__init__.py"]}
                    }
                },
                "tests": {"type": "directory", "files": ["test_main.py"]}
            })
        elif project_type == "desktop_app":
            base_structure["root"]["subdirectories"].update({
                "src": {
                    "type": "directory",
                    "files": ["main.py", "app.py"],
                    "subdirectories": {
                        "gui": {"type": "directory", "files": ["windows.py"]},
                        "core": {"type": "directory", "files": ["logic.py"]},
                        "resources": {"type": "directory", "files": ["assets.py"]}
                    }
                }
            })

        # Add component-specific files
        for component in components:
            component_file = f"{component.lower().replace(' ', '_')}.py"
            if "backend" in base_structure["root"]["subdirectories"]:
                base_structure["root"]["subdirectories"]["backend"]["subdirectories"]["models"]["files"].append(component_file)
            elif "src" in base_structure["root"]["subdirectories"]:
                base_structure["root"]["subdirectories"]["src"]["subdirectories"]["models"]["files"].append(component_file)

        return {
            "structure": base_structure,
            "technology_notes": {
                "framework": tech_stack.get("framework", "Not specified"),
                "database": tech_stack.get("database", "Not specified"),
                "deployment": tech_stack.get("deployment", "Not specified")
            }
        }

    def _generate_database_schema(self, components: List[str]) -> Dict[str, Any]:
        """
        Generate database schema plan based on components.

        Args:
            components: List of main components

        Returns:
            Dictionary containing database schema plan
        """
        schema = {
            "tables": {},
            "relationships": [],
            "indexes": []
        }

        # Generate basic tables from components
        for component in components:
            table_name = component.lower().replace(' ', '_')
            schema["tables"][table_name] = {
                "columns": {
                    "id": {"type": "INTEGER", "primary_key": True, "auto_increment": True},
                    "created_at": {"type": "TIMESTAMP", "default": "CURRENT_TIMESTAMP"},
                    "updated_at": {"type": "TIMESTAMP", "default": "CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"}
                },
                "constraints": [],
                "description": f"Table for {component} data"
            }

        # Add common user table if not present
        if "user" not in schema["tables"] and "users" not in schema["tables"]:
            schema["tables"]["users"] = {
                "columns": {
                    "id": {"type": "INTEGER", "primary_key": True, "auto_increment": True},
                    "email": {"type": "VARCHAR(255)", "unique": True, "not_null": True},
                    "password_hash": {"type": "VARCHAR(255)", "not_null": True},
                    "created_at": {"type": "TIMESTAMP", "default": "CURRENT_TIMESTAMP"},
                    "updated_at": {"type": "TIMESTAMP", "default": "CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"}
                },
                "constraints": [],
                "description": "User authentication and profile data"
            }

        return schema

    def _generate_api_design(self, components: List[str], project_type: str) -> Dict[str, Any]:
        """
        Generate API contract overview.

        Args:
            components: List of main components
            project_type: Type of project

        Returns:
            Dictionary containing API design
        """
        api_design = {
            "base_url": "/api/v1",
            "authentication": {
                "type": "JWT",
                "endpoints": {
                    "login": {"method": "POST", "path": "/auth/login"},
                    "register": {"method": "POST", "path": "/auth/register"},
                    "refresh": {"method": "POST", "path": "/auth/refresh"}
                }
            },
            "endpoints": {},
            "response_format": {
                "success": {"data": "object", "message": "string", "status": "string"},
                "error": {"error": "string", "message": "string", "status": "string"}
            }
        }

        # Generate CRUD endpoints for each component
        for component in components:
            resource_name = component.lower().replace(' ', '_')
            api_design["endpoints"][resource_name] = {
                "list": {
                    "method": "GET",
                    "path": f"/{resource_name}",
                    "description": f"Get all {component} records",
                    "parameters": ["page", "limit", "sort"],
                    "response": f"List of {component} objects"
                },
                "create": {
                    "method": "POST",
                    "path": f"/{resource_name}",
                    "description": f"Create new {component}",
                    "body": f"{component} object data",
                    "response": f"Created {component} object"
                },
                "read": {
                    "method": "GET",
                    "path": f"/{resource_name}/{{id}}",
                    "description": f"Get specific {component} by ID",
                    "parameters": ["id"],
                    "response": f"{component} object"
                },
                "update": {
                    "method": "PUT",
                    "path": f"/{resource_name}/{{id}}",
                    "description": f"Update {component} by ID",
                    "parameters": ["id"],
                    "body": f"Updated {component} object data",
                    "response": f"Updated {component} object"
                },
                "delete": {
                    "method": "DELETE",
                    "path": f"/{resource_name}/{{id}}",
                    "description": f"Delete {component} by ID",
                    "parameters": ["id"],
                    "response": "Deletion confirmation"
                }
            }

        return api_design

    def _generate_component_specs(self, components: List[str], 
                                tech_stack: Dict[str, str]) -> Dict[str, Any]:
        """
        Generate component interface specifications.

        Args:
            components: List of main components
            tech_stack: Dictionary of technology choices

        Returns:
            Dictionary containing component specifications
        """
        specs = {}

        for component in components:
            component_key = component.lower().replace(' ', '_')
            specs[component_key] = {
                "name": component,
                "description": f"Component for handling {component} functionality",
                "interfaces": {
                    "public_methods": [
