        for component in components:
            table_name = component.lower().replace(' ', '_')
            schema["tables"][table_name] = {
                "columns": {
                    "id": {"type": "INTEGER", "primary_key": True, "auto_increment": True},
                    "created_at": {"type": "TIMESTAMP", "default": "CURRENT_TIMESTAMP"},
                    "updated_at": {"type": "TIMESTAMP", "default": "CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"}
                },
                "constraints": [],
                "description": f"Table for {component} data"
            }

        # Add common user table if not present
        if "user" not in schema["tables"] and "users" not in schema["tables"]:
            schema["tables"]["users"] = {
                "columns": {
                    "id": {"type": "INTEGER", "primary_key": True, "auto_increment": True},
                    "email": {"type": "VARCHAR(255)", "unique": True, "not_null": True},
                    "password_hash": {"type": "VARCHAR(255)", "not_null": True},
                    "created_at": {"type": "TIMESTAMP", "default": "CURRENT_TIMESTAMP"},
                    "updated_at": {"type": "TIMESTAMP", "default": "CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"}
                },
                "constraints": [],
                "description": "User authentication and profile data"
            }

