        components = vta_output.get("components", [])
        tech_stack = vta_output.get("suggested_tech_stack", {})

        print(f"📋 Project Type: {project_type}")
        print(f"🔧 Components: {', '.join(components)}")
        print(f"💻 Tech Stack: {tech_stack}")

        # Generate technical architecture
        output = {
            "agent_id": "technical_architect_agent",
            "run_id": str(uuid.uuid4()),
            "timestamp": datetime.now().isoformat(),
            "input_source": vta_output.get("run_id", "unknown"),
            "project_type": project_type,
            "components": components,
            "tech_stack": tech_stack,
            "file_tree": self._generate_file_structure(project_type, components, tech_stack),
            "schema_plan": self._generate_database_schema(components),
            "api_design": self._generate_api_design(components, project_type),
            "component_specs": self._generate_component_specs(components, tech_stack),
            "architecture_notes": {
                "scalability": f"Designed for {project_type} with modular components",
                "security": "JWT authentication, input validation, SQL injection prevention",
                "performance": "Indexed database queries, efficient API design",
                "maintainability": "Clean separation of concerns, well-documented interfaces"
            }
        }

        # Save output
        self._save_output(output)

        print("✅ Technical architecture blueprint generated successfully!")
        print(f"📁 File structure planned for {len(components)} components")
        print(f"🗄️  Database schema with {len(output['schema_plan']['tables'])} tables")
        print(f"🔗 API design with {len(output['api_design']['endpoints'])} resource endpoints")

        return output


