    <script>
        // Load saved data when page loads
        window.addEventListener('load', loadSavedData);

        // Auto-save functionality
        function autoSave() {
            const formData = {
                name: document.getElementById('user-name').value,
                email: document.getElementById('email').value,
                subject: document.getElementById('subject').value,
                message: document.getElementById('message').value
            };
            localStorage.setItem('contactFormData', JSON.stringify(formData));
        }

        function loadSavedData() {
            const savedData = localStorage.getItem('contactFormData');
            if (savedData) {
                const data = JSON.parse(savedData);
                document.getElementById('user-name').value = data.name || '';
                document.getElementById('email').value = data.email || '';
                document.getElementById('subject').value = data.subject || '';
                document.getElementById('message').value = data.message || '';
                updateCharacterCount(); // Update character count for loaded message
            }
        }

        // Real-time validation for name
        document.getElementById('user-name').addEventListener('input', function(e) {
            const name = e.target.value.trim();
            const errorDiv = document.getElementById('name-help');
            const successDiv = document.getElementById('name-success');

            if (name.length < 2) {
                showError('name-help', 'Name must be at least 2 characters long');
                hideSuccess('name-success');
                e.target.style.borderColor = '#dc3545';
            } else {
                hideError('name-help');
                showSuccess('name-success', '✓ Valid name');
                e.target.style.borderColor = '#28a745';
            }
            autoSave();
        });

        // Real-time validation for email
        document.getElementById('email').addEventListener('input', function(e) {
            const email = e.target.value;
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

            if (email && !emailRegex.test(email)) {
                showError('email-help', 'Please enter a valid email address');
                hideSuccess('email-success');
                e.target.style.borderColor = '#dc3545';
            } else if (email) {
                hideError('email-help');
                showSuccess('email-success', '✓ Valid email');
                e.target.style.borderColor = '#28a745';
            } else {
                hideError('email-help');
                hideSuccess('email-success');
                e.target.style.borderColor = '#ddd';
            }
            autoSave();
        });

        // Subject validation
        document.getElementById('subject').addEventListener('change', function(e) {
            if (e.target.value) {
                hideError('subject-help');
                showSuccess('subject-success', '✓ Subject selected');
                e.target.style.borderColor = '#28a745';
            } else {
                showError('subject-help', 'Please select a subject');
                hideSuccess('subject-success');
                e.target.style.borderColor = '#dc3545';
            }
            autoSave();
        });

        // Message validation and character count
        document.getElementById('message').addEventListener('input', function(e) {
            updateCharacterCount();
            const message = e.target.value.trim();

            if (message.length < 10) {
                showError('message-help', 'Message must be at least 10 characters long');
                hideSuccess('message-success');
                e.target.style.borderColor = '#dc3545';
            } else if (message.length > 500) {
                showError('message-help', 'Message must be less than 500 characters');
                hideSuccess('message-success');
                e.target.style.borderColor = '#dc3545';
            } else {
                hideError('message-help');
                showSuccess('message-success', '✓ Good message length');
                e.target.style.borderColor = '#28a745';
            }
            autoSave();
        });

        // Character count update
        function updateCharacterCount() {
            const message = document.getElementById('message').value;
            const countDiv = document.getElementById('message-count');
            countDiv.textContent = `${message.length}/500 characters`;

            if (message.length > 450) {
                countDiv.style.color = '#dc3545';
            } else if (message.length > 400) {
                countDiv.style.color = '#ffc107';
            } else {
                countDiv.style.color = '#666';
            }
        }

        // File upload validation
        document.getElementById('file-upload').addEventListener('change', function(e) {
            const file = e.target.files[0];
            if (file) {
                const maxSize = 5 * 1024 * 1024; // 5MB
                const allowedTypes = ['application/pdf', 'application/msword', 
                                    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                                    'text/plain', 'image/jpeg', 'image/png'];

                if (file.size > maxSize) {
                    showError('file-help', 'File must be smaller than 5MB');
                    hideSuccess('file-success');
                    e.target.value = '';
                } else if (!allowedTypes.includes(file.type)) {
                    showError('file-help', 'File type not allowed. Please use PDF, DOC, TXT, JPG, or PNG');
                    hideSuccess('file-success');
                    e.target.value = '';
                } else {
                    hideError('file-help');
                    showSuccess('file-success', `✓ File "${file.name}" ready to upload`);
                }
            }
        });

        // Form submission
        document.getElementById('contact-form').addEventListener('submit', function(e) {
            e.preventDefault();

            if (validateForm()) {
                submitForm();
            }
        });

        function validateForm() {
            let isValid = true;

            // Validate name
            const name = document.getElementById('user-name').value.trim();
            if (name.length < 2) {
                showError('name-help', 'Name is required and must be at least 2 characters');
                isValid = false;
            }

            // Validate email
            const email = document.getElementById('email').value;
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(email)) {
                showError('email-help', 'Valid email address is required');
                isValid = false;
            }

            // Validate subject
            const subject = document.getElementById('subject').value;
            if (!subject) {
                showError('subject-help', 'Please select a subject');
                isValid = false;
            }

            // Validate message
            const message = document.getElementById('message').value.trim();
            if (message.length < 10 || message.length > 500) {
                showError('message-help', 'Message must be between 10 and 500 characters');
                isValid = false;
            }

            return isValid;
        }

        function submitForm() {
            const submitButton = document.getElementById('submit-btn');
            submitButton.textContent = 'Sending...';
            submitButton.disabled = true;

            // Simulate form submission
            setTimeout(() => {
                submitButton.textContent = 'Message Sent Successfully!';
                submitButton.style.backgroundColor = '#28a745';

                // Clear saved data
                localStorage.removeItem('contactFormData');

                // Reset form after delay
                setTimeout(() => {
                    document.getElementById('contact-form').reset();
                    submitButton.textContent = 'Send Message';
                    submitButton.style.backgroundColor = '#0066cc';
                    submitButton.disabled = false;

                    // Clear all validation states
                    clearAllValidation();
                }, 3000);
            }, 2000);
        }

        // Helper functions
        function showError(elementId, message) {
            const element = document.getElementById(elementId);
            element.textContent = message;
            element.style.display = 'block';
        }

        function hideError(elementId) {
            const element = document.getElementById(elementId);
            element.style.display = 'none';
        }

        function showSuccess(elementId, message) {
            const element = document.getElementById(elementId);
            element.textContent = message;
            element.style.display = 'block';
        }

        function hideSuccess(elementId) {
            const element = document.getElementById(elementId);
            element.style.display = 'none';
        }

        function clearAllValidation() {
            const inputs = document.querySelectorAll('input, textarea, select');
            inputs.forEach(input => {
                input.style.borderColor = '#ddd';
            });

            const errors = document.querySelectorAll('.error-message');
            errors.forEach(error => error.style.display = 'none');

            const successes = document.querySelectorAll('.success-message');
            successes.forEach(success => success.style.display = 'none');

            updateCharacterCount();
        }
    </script>
</body>
</html>
