```javascript
// File upload handling
document.getElementById('fileUpload').addEventListener('change', function(event) {
    const file = event.target.files[0];
    const fileInfo = document.getElementById('fileInfo');
    const fileName = document.getElementById('fileName');
    const fileDetails = document.getElementById('fileDetails');
    const fileError = document.getElementById('fileError');

    // Clear previous displays
    fileInfo.style.display = 'none';
    fileError.style.display = 'none';

    if (file) {
        // Validate file
        const validation = validateFile(file);

        if (validation.valid) {
            // Show file information
            fileName.textContent = file.name;
            fileDetails.innerHTML = `
                Size: ${formatFileSize(file.size)}<br>
                Type: ${file.type || 'Unknown'}<br>
                Last modified: ${new Date(file.lastModified).toLocaleDateString()}
            `;
            fileInfo.style.display = 'block';
        } else {
            // Show error
            fileError.textContent = validation.message;
            fileError.style.display = 'block';
            // Clear the file input
            event.target.value = '';
        }
    }
});

// File validation function
function validateFile(file) {
    const maxSize = 5 * 1024 * 1024; // 5MB in bytes
    const allowedExtensions = ['.jpg', '.jpeg', '.png', '.pdf', '.doc', '.docx', '.txt'];

    // Check file size
    if (file.size > maxSize) {
        return {
            valid: false,
            message: `File size (${formatFileSize(file.size)}) exceeds 5MB limit. Please choose a smaller file.`
        };
    }

    // Check file extension
    const fileName = file.name.toLowerCase();
    const hasValidExtension = allowedExtensions.some(ext => fileName.endsWith(ext));

    if (!hasValidExtension) {
        return {
            valid: false,
            message: `File type not supported. Please choose: ${allowedExtensions.join(', ')}`
        };
    }

    return { valid: true, message: 'File is valid' };
}

// Helper function to format file size
function formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';

    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));

    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

