```javascript
// Global variables
let projects = [];
let editingId = null;

// Load projects when page loads
document.addEventListener('DOMContentLoaded', function() {
    loadProjects();
    displayProjects();
    updateTechFilter();
});

// Handle form submission
document.getElementById('project-form').addEventListener('submit', function(e) {
    e.preventDefault();

    if (editingId) {
        updateProject();
    } else {
        addProject();
    }
});

// Add new project function
function addProject() {
    const title = document.getElementById('title').value;
    const description = document.getElementById('description').value;
    const technologies = document.getElementById('technologies').value;
    const projectUrl = document.getElementById('project-url').value;
    const featured = document.getElementById('featured').checked;

    const project = {
        id: Date.now(),
        title: title,
        description: description,
        technologies: technologies ? technologies.split(',').map(t => t.trim()) : [],
        projectUrl: projectUrl,
        featured: featured,
        dateAdded: new Date().toISOString()
    };

    projects.push(project);
    saveProjects();
    displayProjects();
    updateTechFilter();
    clearForm();

    alert('Project added successfully!');
}

// Update existing project
function updateProject() {
    const title = document.getElementById('title').value;
    const description = document.getElementById('description').value;
    const technologies = document.getElementById('technologies').value;
    const projectUrl = document.getElementById('project-url').value;
    const featured = document.getElementById('featured').checked;

    const projectIndex = projects.findIndex(p => p.id === editingId);
    if (projectIndex !== -1) {
        projects[projectIndex] = {
            ...projects[projectIndex],
            title: title,
            description: description,
            technologies: technologies ? technologies.split(',').map(t => t.trim()) : [],
            projectUrl: projectUrl,
            featured: featured
        };

        saveProjects();
        displayProjects();
        updateTechFilter();
        cancelEdit();

        alert('Project updated successfully!');
    }
}

// Edit project function
function editProject(id) {
    const project = projects.find(p => p.id === id);
    if (project) {
        document.getElementById('title').value = project.title;
        document.getElementById('description').value = project.description;
        document.getElementById('technologies').value = project.technologies.join(', ');
        document.getElementById('project-url').value = project.projectUrl || '';
        document.getElementById('featured').checked = project.featured;

        editingId = id;
        document.getElementById('submit-btn').textContent = 'Update Project';
        document.getElementById('cancel-btn').style.display = 'inline-block';
        document.querySelector('.form-section h2').textContent = 'Edit Project';

        // Scroll to form
        document.querySelector('.form-section').scrollIntoView();
    }
}

// Cancel edit function
function cancelEdit() {
    editingId = null;
    clearForm();
    document.getElementById('submit-btn').textContent = 'Add Project';
    document.getElementById('cancel-btn').style.display = 'none';
    document.querySelector('.form-section h2').textContent = 'Add New Project';
}

// Delete project function
function deleteProject(id) {
    if (confirm('Are you sure you want to delete this project?')) {
        projects = projects.filter(p => p.id !== id);
        saveProjects();
        displayProjects();
        updateTechFilter();
        alert('Project deleted successfully!');
    }
}

// Clear all projects
function clearAllProjects() {
    if (confirm('Are you sure you want to delete ALL projects? This cannot be undone.')) {
        projects = [];
        saveProjects();
        displayProjects();
        updateTechFilter();
        alert('All projects cleared!');
    }
}

// Display projects function
function displayProjects() {
    const container = document.getElementById('projects-container');

    if (projects.length === 0) {
        container.innerHTML = '<div class="no-projects">No projects yet. Add your first project above!</div>';
        return;
    }

    let projectsToShow = [...projects];

    // Apply current filter and sort
    const filterValue = document.getElementById('tech-filter').value;
    const sortValue = document.getElementById('sort-select').value;

    // Filter by technology
    if (filterValue) {
        projectsToShow = projectsToShow.filter(project => 
            project.technologies.some(tech => 
                tech.toLowerCase().includes(filterValue.toLowerCase())
            )
        );
    }

    // Sort projects
    projectsToShow.sort((a, b) => {
        switch(sortValue) {
            case 'oldest':
                return new Date(a.dateAdded) - new Date(b.dateAdded);
            case 'title':
                return a.title.localeCompare(b.title);
            case 'featured':
                if (a.featured === b.featured) {
                    return new Date(b.dateAdded) - new Date(a.dateAdded);
                }
                return b.featured - a.featured;
            default: // newest
                return new Date(b.dateAdded) - new Date(a.dateAdded);
        }
    });

    // Generate HTML
    container.innerHTML = projectsToShow.map(project => `
        <div class="project-card ${project.featured ? 'featured' : ''}">
            <h3 class="project-title">${project.title} ${project.featured ? '⭐' : ''}</h3>
            <p class="project-description">${project.description}</p>
            <div class="tech-tags">
                ${project.technologies.map(tech => `<span class="tech-tag">${tech}</span>`).join('')}
            </div>
            <div class="project-meta">
                Added: ${new Date(project.dateAdded).toLocaleDateString()}
            </div>
            <div class="project-actions">
                ${project.projectUrl ? `<button class="view-btn" onclick="window.open('${project.projectUrl}', '_blank')">View Project</button>` : ''}
                <button class="edit-btn" onclick="editProject(${project.id})">Edit</button>
                <button class="delete-btn" onclick="deleteProject(${project.id})">Delete</button>
            </div>
        </div>
    `).join('');
}

// Update technology filter dropdown
function updateTechFilter() {
    const select = document.getElementById('tech-filter');
    const allTechs = new Set();

    projects.forEach(project => {
        project.technologies.forEach(tech => allTechs.add(tech));
    });

    // Keep current selection
    const currentValue = select.value;

    // Clear and rebuild options
    select.innerHTML = '<option value="">All Technologies</option>';

    Array.from(allTechs).sort().forEach(tech => {
        const option = document.createElement('option');
        option.value = tech;
        option.textContent = tech;
        select.appendChild(option);
    });

    // Restore selection
    select.value = currentValue;
}

// Filter projects by technology
function filterProjects() {
    displayProjects();
}

// Sort projects
function sortProjects() {
    displayProjects();
}

// Clear form
function clearForm() {
    document.getElementById('project-form').reset();
}

// Save projects to localStorage
function saveProjects() {
    localStorage.setItem('bryces-projects', JSON.stringify(projects));
}

// Load projects from localStorage
function loadProjects() {
    const saved = localStorage.getItem('bryces-projects');
    if (saved) {
        projects = JSON.parse(saved);
    }
}
```

