**JavaScript for Advanced Search and Analytics:**
```javascript
// Add these functions to your existing JavaScript

// Initialize advanced search
document.addEventListener('DOMContentLoaded', function() {
    displayProjects();
    updateAnalytics();
    populateTechFilter();
    setupSearchListeners();
});

function setupSearchListeners() {
    document.getElementById('global-search').addEventListener('input', applyFilters);
    document.getElementById('status-filter').addEventListener('change', applyFilters);
    document.getElementById('tech-filter').addEventListener('change', applyFilters);
}

function populateTechFilter() {
    const projects = JSON.parse(localStorage.getItem('projects')) || [];
    const allTechs = new Set();

    projects.forEach(project => {
        if (project.technologies) {
            project.technologies.forEach(tech => allTechs.add(tech));
        }
    });

    const techFilter = document.getElementById('tech-filter');
    techFilter.innerHTML = '<option value="">All Technologies</option>';

    Array.from(allTechs).sort().forEach(tech => {
        techFilter.innerHTML += `<option value="${tech}">${tech}</option>`;
    });
}

function applyFilters() {
    const searchTerm = document.getElementById('global-search').value.toLowerCase();
    const statusFilter = document.getElementById('status-filter').value;
    const techFilter = document.getElementById('tech-filter').value;

    const projects = JSON.parse(localStorage.getItem('projects')) || [];

    const filteredProjects = projects.filter(project => {
        const matchesSearch = project.name.toLowerCase().includes(searchTerm) ||
                            project.description.toLowerCase().includes(searchTerm);

        const matchesStatus = !statusFilter || project.status === statusFilter;

        const matchesTech = !techFilter || 
                          (project.technologies && project.technologies.includes(techFilter));

        return matchesSearch && matchesStatus && matchesTech;
    });

    displayFilteredProjects(filteredProjects);
}

function displayFilteredProjects(projects) {
    const projectsList = document.getElementById('projects-list');

    if (projects.length === 0) {
        projectsList.innerHTML = '<p class="no-results">No projects match your search criteria.</p>';
        return;
    }

    let html = '';
    projects.forEach(project => {
        html += createProjectCard(project);
    });

    projectsList.innerHTML = html;
}

// Enhanced project card with image support
function createProjectCard(project) {
    const techTags = project.technologies ? 
        project.technologies.map(tech => `<span class="tech-tag">${tech}</span>`).join('') : '';

    const imageHtml = project.image ? 
        `<img src="${project.image}" alt="${project.name}" class="project-image">` : '';

    const featuredClass = project.featured ? 'featured-project' : '';

    return `
        <div class="project-card ${featuredClass}" data-id="${project.id}">
            ${imageHtml}
            <div class="project-content">
                <h3>${project.name} ${project.featured ? '⭐' : ''}</h3>
                <p>${project.description}</p>
                <div class="tech-tags">${techTags}</div>
                <p class="project-status">Status: ${project.status}</p>
                <p class="project-date">Added: ${new Date(project.dateAdded).toLocaleDateString()}</p>
                <div class="project-actions">
                    <button onclick="editProject(${project.id})" class="edit-btn">Edit</button>
                    <button onclick="deleteProject(${project.id})" class="delete-btn">Delete</button>
                </div>
            </div>
        </div>
    `;
}

function updateAnalytics() {
    const projects = JSON.parse(localStorage.getItem('projects')) || [];

    document.getElementById('total-projects').textContent = projects.length;
    document.getElementById('completed-projects').textContent = 
        projects.filter(p => p.status === 'Completed').length;
    document.getElementById('in-progress-projects').textContent = 
        projects.filter(p => p.status === 'In Progress').length;
    document.getElementById('featured-projects').textContent = 
        projects.filter(p => p.featured).length;
}

function clearAllFilters() {
    document.getElementById('global-search').value = '';
    document.getElementById('status-filter').value = '';
    document.getElementById('tech-filter').value = '';
    displayProjects();
}

// Export functionality
function exportProjects() {
    const projects = JSON.parse(localStorage.getItem('projects')) || [];
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(projects, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "my-projects.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
}
```

