// File validation function
function validateFile(file) {
  const maxSize = 5 * 1024 * 1024; // 5MB in bytes
  const allowedExtensions = [
    ".jpg",
    ".jpeg",
    ".png",
    ".pdf",
    ".doc",
    ".docx",
    ".txt",
  ];

  // Check file size
  if (file.size > maxSize) {
    return {
      valid: false,
      message: `File size (${formatFileSize(
        file.size
      )}) exceeds 5MB limit. Please choose a smaller file.`,
    };
  }

  // Check file extension
  const fileName = file.name.toLowerCase();
  const hasValidExtension = allowedExtensions.some((ext) =>
    fileName.endsWith(ext)
  );

  if (!hasValidExtension) {
    return {
      valid: false,
      message: `File type not supported. Please choose: ${allowedExtensions.join(
        ", "
      )}`,
    };
  }

  return { valid: true, message: "File is valid" };
}

// Helper function to format file size
function formatFileSize(bytes) {
  if (bytes === 0) return "0 Bytes";

  const k = 1024;
  const sizes = ["Bytes", "KB", "MB", "GB"];
  const i = Math.floor(Math.log(bytes) / Math.log(k));

  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
}

// Enhanced form validation including file upload
function validateAndSubmitForm() {
  // Get all existing form values
  let name = document.getElementById("visitorName");
  let email = document.getElementById("visitorEmail");
  let message = document.getElementById("visitorMessage") || document.getElementById("message");
  let reason = document.getElementById("contactReason");
  let howFound = document.getElementById("howDidYouFind");
  let gradeLevel = getRadioValue("gradeLevel");
  let learningStyle = getRadioValue("learningStyle");
  let programmingInterests = getCheckedValues("programmingInterests");
  let websiteFeatures = getCheckedValues("websiteFeatures");

  // Get file upload information
  let fileInput = document.getElementById("fileUpload");
  let uploadedFile = fileInput ? fileInput.files[0] : null;

  let resultDiv = document.getElementById("formResult");

  // Clear previous results
  if (resultDiv) {
    resultDiv.innerHTML = "";
    resultDiv.className = "";
  }

  // Helper function for showing errors in form validation
  function showFormError(message) {
    if (resultDiv) {
      resultDiv.innerHTML = message;
      resultDiv.className = "error";
    }
  }

  function showFormSuccess(message) {
    if (resultDiv) {
      resultDiv.innerHTML = message;
      resultDiv.className = "success";
    }
  }

  // Validation checks
  if (!name || name.value.trim() === "") {
    showFormError("Please enter your name so I know who is contacting me!");
    return;
  }

  if (name.value.trim().length < 2) {
    showFormError("Please enter your full name (at least 2 characters).");
    return;
  }

  if (!email || email.value.trim() === "") {
    showFormError("Please enter your email address so I can reply to you!");
    return;
  }

  if (!isValidEmail(email.value.trim())) {
    showFormError("Please enter a valid email address (like: name@example.com).");
    return;
  }

  if (!reason || reason.value === "") {
    showFormError("Please select a reason for contacting me.");
    return;
  }

  if (!howFound || howFound.value === "") {
    showFormError("Please let me know how you found my website.");
    return;
  }

  if (!gradeLevel) {
    showFormError("Please select your current grade level.");
    return;
  }

  if (!learningStyle) {
    showFormError("Please select your preferred learning style.");
    return;
  }

  if (programmingInterests.length === 0) {
    showFormError(
      "Please select at least one programming area that interests you."
    );
    return;
  }

  if (websiteFeatures.length === 0) {
    showFormError("Please select at least one website feature you'd like to see.");
    return;
  }

  if (!message || message.value.trim() === "") {
    showFormError("Please write a message to tell me why you are contacting me!");
    return;
  }

  // File validation (optional, so only validate if file is selected)
  if (uploadedFile) {
    const fileValidation = validateFile(uploadedFile);
    if (!fileValidation.valid) {
      showFormError(`File upload problem: ${fileValidation.message}`);
      return;
    }
  }

  if (message.value.trim().length < 10) {
    showFormError(
      "Please write a longer message so I can understand what you need."
    );
    return;
  }

  // Create comprehensive success message including file info
  let interestsList = document.getElementById("projectInterests");
  let selectedInterests = [];
  if (interestsList) {
    for (let i = 0; i < interestsList.options.length; i++) {
      if (interestsList.options[i].selected) {
        selectedInterests.push(interestsList.options[i].text);
      }
    }
  }

  let fileMessage = uploadedFile
    ? `📎 File attached: ${uploadedFile.name} (${formatFileSize(
        uploadedFile.size
      )})`
    : "📎 No file attached";

  showFormSuccess(`
    Thank you, ${name.value.trim()}! I received your complete information:<br />
    Contact reason: ${reason.value}<br />
    Grade level: ${gradeLevel}<br />
    Programming interests: ${programmingInterests.join(", ")}<br />
    Learning style: ${learningStyle}<br />
    Requested features: ${websiteFeatures.join(", ")}<br />
    ${fileMessage}<br /><br />

    I'll reply to ${email.value.trim()} with personalized resources and respond to your message!
  `);
  clearForm();
}

// Helper function to get radio button value
function getRadioValue(radioName) {
  let radios = document.getElementsByName(radioName);
  for (let i = 0; i < radios.length; i++) {
    if (radios[i].checked) {
      return radios[i].value;
    }
  }
  return null;
}

// Helper function to get checked checkbox values
function getCheckedValues(checkboxName) {
  let checkboxes = document.getElementsByName(checkboxName);
  let checkedValues = [];

  for (let i = 0; i < checkboxes.length; i++) {
    if (checkboxes[i].checked) {
      checkedValues.push(checkboxes[i].value);
    }
  }

  return checkedValues;
}

// Helper function to validate email format
function isValidEmail(email) {
  return (
    email.includes("@") &&
    email.includes(".") &&
    email.indexOf("@") < email.lastIndexOf(".")
  );
}

// Enhanced form clearing including new inputs
function clearForm() {
  const elements = [
    "visitorName",
    "visitorEmail", 
    "visitorMessage",
    "message",
    "contactReason",
    "howDidYouFind"
  ];

  elements.forEach(id => {
    const element = document.getElementById(id);
    if (element) element.value = "";
  });

  // Clear multiple select
  let interests = document.getElementById("projectInterests");
  if (interests) {
    for (let i = 0; i < interests.options.length; i++) {
      interests.options[i].selected = false;
    }
  }

  // Clear radio buttons
  clearRadioButtons("gradeLevel");
  clearRadioButtons("learningStyle");

  // Clear checkboxes
  clearCheckboxes("programmingInterests");
  clearCheckboxes("websiteFeatures");

  // Hide follow-up questions
  const followUpDiv = document.getElementById("followUpQuestions");
  if (followUpDiv) followUpDiv.style.display = "none";

  // Clear file upload
  const fileUpload = document.getElementById("fileUpload");
  const fileInfo = document.getElementById("fileInfo");
  const fileError = document.getElementById("fileError");

  if (fileUpload) fileUpload.value = "";
  if (fileInfo) fileInfo.style.display = "none";
  if (fileError) fileError.style.display = "none";
}

function clearRadioButtons(radioName) {
  let radios = document.getElementsByName(radioName);
  for (let i = 0; i < radios.length; i++) {
    radios[i].checked = false;
  }
}

// Helper function to clear checkbox groups
function clearCheckboxes(checkboxName) {
  let checkboxes = document.getElementsByName(checkboxName);
  for (let i = 0; i < checkboxes.length; i++) {
    checkboxes[i].checked = false;
  }
}

