import React, { useState, useRef, useEffect } from 'react';
import { Plus, ChevronRight, ChevronDown, FileText, Folder, Search, Bold, Italic, Underline, List, AlignLeft, AlignCenter, AlignRight, Type, Palette, Trash2 } from 'lucide-react';

const OneNoteClone = () => {
  const [notebooks, setNotebooks] = useState([
    {
      id: 1,
      name: 'My Notebook',
      expanded: true,
      sections: [
        {
          id: 1,
          name: 'General',
          pages: [
            { id: 1, title: 'Welcome', content: '<h1>Welcome to Your Notes</h1><p>Start typing to create your first note...</p>', lastModified: new Date() }
          ]
        }
      ]
    }
  ]);

  const [activeNotebook, setActiveNotebook] = useState(1);
  const [activeSection, setActiveSection] = useState(1);
  const [activePage, setActivePage] = useState(1);
  const [searchTerm, setSearchTerm] = useState('');
  const [isFormatToolbarVisible, setIsFormatToolbarVisible] = useState(false);

  const editorRef = useRef(null);

  const getCurrentPage = () => {
    const notebook = notebooks.find(nb => nb.id === activeNotebook);
    const section = notebook?.sections.find(s => s.id === activeSection);
    return section?.pages.find(p => p.id === activePage);
  };

  const updatePageContent = (content) => {
    setNotebooks(prev => prev.map(notebook => ({
      ...notebook,
      sections: notebook.sections.map(section => ({
        ...section,
        pages: section.pages.map(page => 
          page.id === activePage 
            ? { ...page, content, lastModified: new Date() }
            : page
        )
      }))
    })));
  };

  const addNotebook = () => {
    const newId = Math.max(...notebooks.map(nb => nb.id)) + 1;
    setNotebooks(prev => [...prev, {
      id: newId,
      name: `Notebook ${newId}`,
      expanded: true,
      sections: [{
        id: 1,
        name: 'New Section',
        pages: [{ id: 1, title: 'Untitled Page', content: '<p>Start writing...</p>', lastModified: new Date() }]
      }]
    }]);
    setActiveNotebook(newId);
    setActiveSection(1);
    setActivePage(1);
  };

  const addSection = (notebookId) => {
    setNotebooks(prev => prev.map(notebook => {
      if (notebook.id === notebookId) {
        const newSectionId = Math.max(...notebook.sections.map(s => s.id)) + 1;
        return {
          ...notebook,
          sections: [...notebook.sections, {
            id: newSectionId,
            name: `Section ${newSectionId}`,
            pages: [{ id: 1, title: 'Untitled Page', content: '<p>Start writing...</p>', lastModified: new Date() }]
          }]
        };
      }
      return notebook;
    }));
  };

  const addPage = (notebookId, sectionId) => {
    setNotebooks(prev => prev.map(notebook => {
      if (notebook.id === notebookId) {
        return {
          ...notebook,
          sections: notebook.sections.map(section => {
            if (section.id === sectionId) {
              const newPageId = Math.max(...section.pages.map(p => p.id)) + 1;
              const newPage = { 
                id: newPageId, 
                title: 'Untitled Page', 
                content: '<p>Start writing...</p>', 
                lastModified: new Date() 
              };
              return {
                ...section,
                pages: [...section.pages, newPage]
              };
            }
            return section;
          })
        };
      }
      return notebook;
    }));
  };

  const toggleNotebook = (notebookId) => {
    setNotebooks(prev => prev.map(notebook => 
      notebook.id === notebookId 
        ? { ...notebook, expanded: !notebook.expanded }
        : notebook
    ));
  };

  const formatText = (command, value = null) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
  };

  const handleEditorInput = () => {
    if (editorRef.current) {
      updatePageContent(editorRef.current.innerHTML);
    }
  };

  const handleTitleChange = (e) => {
    const newTitle = e.target.value;
    setNotebooks(prev => prev.map(notebook => ({
      ...notebook,
      sections: notebook.sections.map(section => ({
        ...section,
        pages: section.pages.map(page => 
          page.id === activePage 
            ? { ...page, title: newTitle }
            : page
        )
      }))
    })));
  };

  const deletePage = (notebookId, sectionId, pageId) => {
    setNotebooks(prev => prev.map(notebook => {
      if (notebook.id === notebookId) {
        return {
          ...notebook,
          sections: notebook.sections.map(section => {
            if (section.id === sectionId) {
              const newPages = section.pages.filter(p => p.id !== pageId);
              if (newPages.length === 0) {
                newPages.push({ id: Date.now(), title: 'Untitled Page', content: '<p>Start writing...</p>', lastModified: new Date() });
              }
              if (pageId === activePage) {
                setActivePage(newPages[0].id);
              }
              return { ...section, pages: newPages };
            }
            return section;
          })
        };
      }
      return notebook;
    }));
  };

  const currentPage = getCurrentPage();

  const filteredNotebooks = notebooks.map(notebook => ({
    ...notebook,
    sections: notebook.sections.map(section => ({
      ...section,
      pages: section.pages.filter(page => 
        page.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        page.content.toLowerCase().includes(searchTerm.toLowerCase())
      )
    }))
  }));

  useEffect(() => {
    if (editorRef.current && currentPage) {
      editorRef.current.innerHTML = currentPage.content;
    }
  }, [activePage]);

  return (
    <div className="flex h-screen bg-gray-50">
      {/* Sidebar */}
      <div className="w-80 bg-white border-r border-gray-200 flex flex-col">
        {/* Search */}
        <div className="p-4 border-b border-gray-200">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input
              type="text"
              placeholder="Search notes..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>

        {/* Notebooks */}
        <div className="flex-1 overflow-y-auto">
          <div className="p-2">
            <div className="flex items-center justify-between mb-2">
              <h3 className="text-sm font-semibold text-gray-600 uppercase tracking-wide">Notebooks</h3>
              <button
                onClick={addNotebook}
                className="p-1 hover:bg-gray-100 rounded"
                title="Add Notebook"
              >
                <Plus className="w-4 h-4 text-gray-500" />
              </button>
            </div>

            {filteredNotebooks.map(notebook => (
              <div key={notebook.id} className="mb-2">
                <div 
                  className={`flex items-center justify-between p-2 rounded cursor-pointer hover:bg-gray-100 ${
                    activeNotebook === notebook.id ? 'bg-blue-50 text-blue-700' : ''
                  }`}
                  onClick={() => {
                    setActiveNotebook(notebook.id);
                    toggleNotebook(notebook.id);
                  }}
                >
                  <div className="flex items-center">
                    {notebook.expanded ? (
                      <ChevronDown className="w-4 h-4 mr-1" />
                    ) : (
                      <ChevronRight className="w-4 h-4 mr-1" />
                    )}
                    <Folder className="w-4 h-4 mr-2" />
                    <span className="text-sm font-medium">{notebook.name}</span>
                  </div>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      addSection(notebook.id);
                    }}
                    className="p-1 hover:bg-gray-200 rounded"
                    title="Add Section"
                  >
                    <Plus className="w-3 h-3" />
                  </button>
                </div>

                {notebook.expanded && (
                  <div className="ml-4">
                    {notebook.sections.map(section => (
                      <div key={section.id} className="mb-1">
                        <div 
                          className={`flex items-center justify-between p-2 rounded cursor-pointer hover:bg-gray-100 ${
                            activeSection === section.id ? 'bg-blue-50 text-blue-700' : ''
                          }`}
                          onClick={() => {
                            setActiveSection(section.id);
                            if (section.pages.length > 0) {
                              setActivePage(section.pages[0].id);
                            }
                          }}
                        >
                          <div className="flex items-center">
                            <span className="text-sm">{section.name}</span>
                          </div>
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              addPage(notebook.id, section.id);
                            }}
                            className="p-1 hover:bg-gray-200 rounded"
                            title="Add Page"
                          >
                            <Plus className="w-3 h-3" />
                          </button>
                        </div>

                        <div className="ml-4">
                          {section.pages.map(page => (
                            <div
                              key={page.id}
                              className={`flex items-center justify-between p-2 rounded cursor-pointer hover:bg-gray-100 ${
                                activePage === page.id ? 'bg-blue-100 text-blue-800' : ''
                              }`}
                              onClick={() => setActivePage(page.id)}
                            >
                              <div className="flex items-center min-w-0">
                                <FileText className="w-3 h-3 mr-2 flex-shrink-0" />
                                <span className="text-xs truncate">{page.title}</span>
                              </div>
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  deletePage(notebook.id, section.id, page.id);
                                }}
                                className="p-1 hover:bg-gray-200 rounded opacity-0 group-hover:opacity-100"
                                title="Delete Page"
                              >
                                <Trash2 className="w-3 h-3 text-red-500" />
                              </button>
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col">
        {currentPage && (
          <>
            {/* Title Bar */}
            <div className="bg-white border-b border-gray-200 p-4">
              <input
                type="text"
                value={currentPage.title}
                onChange={handleTitleChange}
                className="text-2xl font-bold w-full border-none outline-none bg-transparent"
                placeholder="Page title..."
              />
              <div className="text-xs text-gray-500 mt-1">
                Last modified: {currentPage.lastModified.toLocaleString()}
              </div>
            </div>

            {/* Toolbar */}
            <div className="bg-white border-b border-gray-200 p-2">
              <div className="flex items-center space-x-1">
                <button
                  onClick={() => formatText('bold')}
                  className="p-2 hover:bg-gray-100 rounded"
                  title="Bold"
                >
                  <Bold className="w-4 h-4" />
                </button>
                <button
                  onClick={() => formatText('italic')}
                  className="p-2 hover:bg-gray-100 rounded"
                  title="Italic"
                >
                  <Italic className="w-4 h-4" />
                </button>
                <button
                  onClick={() => formatText('underline')}
                  className="p-2 hover:bg-gray-100 rounded"
                  title="Underline"
                >
                  <Underline className="w-4 h-4" />
                </button>

                <div className="w-px h-6 bg-gray-300 mx-2"></div>

                <button
                  onClick={() => formatText('insertUnorderedList')}
                  className="p-2 hover:bg-gray-100 rounded"
                  title="Bullet List"
                >
                  <List className="w-4 h-4" />
                </button>

                <div className="w-px h-6 bg-gray-300 mx-2"></div>

                <button
                  onClick={() => formatText('justifyLeft')}
                  className="p-2 hover:bg-gray-100 rounded"
                  title="Align Left"
                >
                  <AlignLeft className="w-4 h-4" />
                </button>
                <button
                  onClick={() => formatText('justifyCenter')}
                  className="p-2 hover:bg-gray-100 rounded"
                  title="Align Center"
                >
                  <AlignCenter className="w-4 h-4" />
                </button>
                <button
                  onClick={() => formatText('justifyRight')}
                  className="p-2 hover:bg-gray-100 rounded"
                  title="Align Right"
                >
                  <AlignRight className="w-4 h-4" />
                </button>

                <div className="w-px h-6 bg-gray-300 mx-2"></div>

                <select 
                  onChange={(e) => formatText('fontSize', e.target.value)}
                  className="px-2 py-1 border border-gray-300 rounded text-sm"
                  defaultValue="3"
                >
                  <option value="1">8pt</option>
                  <option value="2">10pt</option>
                  <option value="3">12pt</option>
                  <option value="4">14pt</option>
                  <option value="5">18pt</option>
                  <option value="6">24pt</option>
                  <option value="7">36pt</option>
                </select>

                <input
                  type="color"
                  onChange={(e) => formatText('foreColor', e.target.value)}
                  className="w-8 h-8 border border-gray-300 rounded cursor-pointer"
                  title="Text Color"
                />
              </div>
            </div>

            {/* Editor */}
            <div className="flex-1 bg-white p-6 overflow-y-auto">
              <div
                ref={editorRef}
                contentEditable
                onInput={handleEditorInput}
                className="min-h-full outline-none"
                style={{ 
                  lineHeight: '1.6',
                  fontSize: '14px',
                  fontFamily: 'system-ui, -apple-system, sans-serif'
                }}
                suppressContentEditableWarning={true}
              />
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default OneNoteClone;

