const updatePageContent = (content) => {
  setNotebooks(prev => prev.map(notebook => ({
    ...notebook,
    sections: notebook.sections.map(section => ({
      ...section,
      pages: section.pages.map(page => 
        page.id === activePage 
          ? { ...page, content, lastModified: new Date() }
          : page
      )
    }))
  })));
};

const updatePageDrawings = (drawings) => {
  setNotebooks(prev => prev.map(notebook => ({
    ...notebook,
    sections: notebook.sections.map(section => ({
      ...section,
      pages: section.pages.map(page => 
        page.id === activePage 
          ? { ...page, drawings, lastModified: new Date() }
          : page
      )
    }))
  })));
};

const saveDrawingState = () => {
  if (canvasRef.current) {
    const canvas = canvasRef.current;
    const imageData = canvas.toDataURL();
    const newHistory = drawingHistory.slice(0, historyStep + 1);
    newHistory.push(imageData);
    setDrawingHistory(newHistory);
    setHistoryStep(newHistory.length - 1);

    // Also save to page data
    const currentPage = getCurrentPage();
    if (currentPage) {
      const newDrawings = [...(currentPage.drawings || []), { 
        id: Date.now(), 
        imageData,
        timestamp: new Date()
      }];
      updatePageDrawings(newDrawings);
    }
  }
};

const undoDrawing = () => {
  if (historyStep > 0) {
    const canvas = canvasRef.current;
    const ctx = drawingContextRef.current;
    const previousState = drawingHistory[historyStep - 1];

    const img = new Image();
    img.onload = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(img, 0, 0);
    };
    img.src = previousState;

    setHistoryStep(historyStep - 1);
  }
};

const redoDrawing = () => {
  if (historyStep < drawingHistory.length - 1) {
    const canvas = canvasRef.current;
    const ctx = drawingContextRef.current;
    const nextState = drawingHistory[historyStep + 1];

    const img = new Image();
    img.onload = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(img, 0, 0);
    };
    img.src = nextState;

    setHistoryStep(historyStep + 1);
  }
};

const clearCanvas = () => {
  if (canvasRef.current && drawingContextRef.current) {
    const canvas = canvasRef.current;
    const ctx = drawingContextRef.current;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    saveDrawingState();
  }
};

const startDrawing = (e) => {
  if (currentTool === 'text') return;

  setIsDrawing(true);
  const canvas = canvasRef.current;
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  const ctx = drawingContextRef.current;
  ctx.beginPath();
  ctx.moveTo(x, y);

  if (currentTool === 'eraser') {
    ctx.globalCompositeOperation = 'destination-out';
  } else {
    ctx.globalCompositeOperation = 'source-over';
    ctx.strokeStyle = penColor;
  }

  ctx.lineWidth = penSize;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
};

const draw = (e) => {
  if (!isDrawing || currentTool === 'text') return;

  const canvas = canvasRef.current;
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  const ctx = drawingContextRef.current;

  if (currentTool === 'pen' || currentTool === 'eraser') {
    ctx.lineTo(x, y);
    ctx.stroke();
  }
};

const stopDrawing = () => {
  if (isDrawing) {
    setIsDrawing(false);
    saveDrawingState();
  }
};

const initializeCanvas = () => {
  const canvas = canvasRef.current;
  if (canvas) {
    const ctx = canvas.getContext('2d');
    drawingContextRef.current = ctx;

    // Set canvas size to match container
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // Initialize drawing history
    const initialState = canvas.toDataURL();
    setDrawingHistory([initialState]);
    setHistoryStep(0);
  }
};

