const getWordCount = (html) => {
  // Strip HTML tags and get plain text
  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = html;
  const text = tempDiv.textContent || tempDiv.innerText || '';

  // Count words (split by whitespace and filter out empty strings)
  const words = text.trim().split(/\s+/).filter(word => word.length > 0);
  return words.length === 1 && words[0] === '' ? 0 : words.length;
};

const getCharacterCount = (html) => {
  // Strip HTML tags and get plain text
  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = html;
  const text = tempDiv.textContent || tempDiv.innerText || '';
  return text.length;
};

const getCharacterCountWithSpaces = (html) => {
  // Strip HTML tags and get plain text including spaces
  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = html;
  const text = tempDiv.textContent || tempDiv.innerText || '';
  return text.length;
};

const getCharacterCountWithoutSpaces = (html) => {
  // Strip HTML tags and get plain text without spaces
  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = html;
  const text = tempDiv.textContent || tempDiv.innerText || '';
  return text.replace(/\s/g, '').length;
};

