class AICoordinator:
    def __init__(self, config: Dict[str, str] = None):
        self.providers = {}
        self.config = config or {}
        self._initialize_providers()
        self.usage_stats = {
            "total_requests": 0,
            "total_cost": 0.0,
            "provider_usage": {},
            "task_type_usage": {}
        }

    def _initialize_providers(self):
        """Initialize available AI providers based on configuration"""
        if self.config.get("OPENAI_API_KEY"):
            self.providers[AIProvider.OPENAI] = OpenAIProvider(
                self.config["OPENAI_API_KEY"]
            )

        if self.config.get("ANTHROPIC_API_KEY"):
            self.providers[AIProvider.ANTHROPIC] = AnthropicProvider(
                self.config["ANTHROPIC_API_KEY"]
            )

        # Local provider (always available if endpoint is running)
        self.providers[AIProvider.LOCAL] = LocalAIProvider(
            self.config.get("LOCAL_AI_URL", "http://localhost:11434")
        )

    async def process_request(self, request: AIRequest) -> AIResponse:
        """Process AI request with automatic provider selection and fallback"""
        provider = self._select_provider(request)

        try:
            response = await self._execute_with_retry(provider, request)
            self._update_usage_stats(provider, request, response)
            return response

        except Exception as e:
            # Try fallback provider
            fallback_provider = self._get_fallback_provider(provider, request)
            if fallback_provider and fallback_provider != provider:
                try:
                    response = await self._execute_with_retry(fallback_provider, request)
                    self._update_usage_stats(fallback_provider, request, response)
                    return response
                except Exception as fallback_error:
                    raise Exception(f"Both primary ({e}) and fallback ({fallback_error}) failed")
            else:
                raise e

    def _select_provider(self, request: AIRequest) -> AIProvider:
        """Select the best provider for the request"""
        if request.preferred_provider and request.preferred_provider in self.providers:
            return request.preferred_provider

        # Provider selection logic based on task type and availability
        task_preferences = {
            TaskType.VISION_TRANSLATION: [AIProvider.ANTHROPIC, AIProvider.OPENAI, AIProvider.LOCAL],
            TaskType.CODE_GENERATION: [AIProvider.OPENAI, AIProvider.LOCAL, AIProvider.ANTHROPIC],
            TaskType.ARCHITECTURE_DESIGN: [AIProvider.ANTHROPIC, AIProvider.OPENAI, AIProvider.LOCAL],
            TaskType.UX_DESIGN: [AIProvider.OPENAI, AIProvider.ANTHROPIC, AIProvider.LOCAL],
            TaskType.SYSTEM_EVALUATION: [AIProvider.ANTHROPIC, AIProvider.OPENAI, AIProvider.LOCAL],
            TaskType.CONTENT_CREATION: [AIProvider.OPENAI, AIProvider.ANTHROPIC, AIProvider.LOCAL]
        }

        preferred_providers = task_preferences.get(request.task_type, [AIProvider.OPENAI])

        for provider in preferred_providers:
            if provider in self.providers:
                return provider

        # Fallback to any available provider
        if self.providers:
            return next(iter(self.providers.keys()))

        raise Exception("No AI providers available")

    def _get_fallback_provider(self, failed_provider: AIProvider, request: AIRequest) -> Optional[AIProvider]:
        """Get fallback provider when primary fails"""
        available_providers = list(self.providers.keys())
        available_providers = [p for p in available_providers if p != failed_provider]

        if available_providers:
            # Prefer local provider as fallback (no cost, usually reliable)
            if AIProvider.LOCAL in available_providers:
                return AIProvider.LOCAL
            return available_providers[0]

        return None

    async def _execute_with_retry(self, provider: AIProvider, request: AIRequest, max_retries: int = 3) -> AIResponse:
        """Execute request with retry logic"""
        last_exception = None

        for attempt in range(max_retries):
            try:
                return await self.providers[provider].generate_response(request)
            except Exception as e:
                last_exception = e
                if attempt < max_retries - 1:
                    await asyncio.sleep(2 ** attempt)  # Exponential backoff

        raise last_exception

    def _update_usage_stats(self, provider: AIProvider, request: AIRequest, response: AIResponse):
        """Update usage statistics"""
        self.usage_stats["total_requests"] += 1

        # Estimate cost
        cost = self.providers[provider].estimate_cost(request)
        self.usage_stats["total_cost"] += cost

        # Provider usage
        if provider.value not in self.usage_stats["provider_usage"]:
            self.usage_stats["provider_usage"][provider.value] = {
                "requests": 0, "cost": 0.0, "avg_response_time": 0.0
            }

        provider_stats = self.usage_stats["provider_usage"][provider.value]
        provider_stats["requests"] += 1
        provider_stats["cost"] += cost
        provider_stats["avg_response_time"] = (
            (provider_stats["avg_response_time"] * (provider_stats["requests"] - 1) + 
             response.execution_time_seconds) / provider_stats["requests"]
        )

        # Task type usage
        task_key = request.task_type.value
        if task_key not in self.usage_stats["task_type_usage"]:
            self.usage_stats["task_type_usage"][task_key] = {"requests": 0, "cost": 0.0}

        self.usage_stats["task_type_usage"][task_key]["requests"] += 1
        self.usage_stats["task_type_usage"][task_key]["cost"] += cost

    def get_usage_stats(self) -> Dict[str, Any]:
        """Get current usage statistics"""
        return self.usage_stats.copy()

    async def test_providers(self) -> Dict[AIProvider, bool]:
        """Test all configured providers"""
        test_request = AIRequest(
            task_type=TaskType.CONTENT_CREATION,
            prompt="Respond with 'OK' if you can process this request.",
            context={},
            temperature=0.1,
            max_tokens=10
        )

        results = {}
        for provider in self.providers:
            try:
                response = await self.providers[provider].generate_response(test_request)
                results[provider] = "OK" in response.content.upper()
            except Exception:
                results[provider] = False

        return results

