class EnhancedVisionTranslatorAgent:
    def __init__(self, ai_coordinator: AICoordinator):
        self.ai_coordinator = ai_coordinator

    async def translate_vision(self, vision_input: str, project_name: str, context: Dict = None) -> Dict:
        """Translate vision using AI coordination"""
        request = AIRequest(
            task_type=TaskType.VISION_TRANSLATION,
            prompt=vision_input,
            context={
                "project_name": project_name,
                "additional_context": context or {},
                "system_capabilities": ["web_development", "mobile_apps", "automation", "data_processing"],
                "constraint_templates": {
                    "timeline": ["1 week", "1 month", "3 months", "6 months"],
                    "complexity": ["simple", "moderate", "complex", "enterprise"],
                    "budget": ["minimal", "moderate", "substantial", "enterprise"]
                }
            },
            temperature=0.7,
            max_tokens=2000
        )

        response = await self.ai_coordinator.process_request(request)

        try:
            # Parse JSON response
            vision_spec = json.loads(response.content)
            return {
                "vision_spec": vision_spec,
                "ai_metadata": {
                    "provider": response.provider.value,
                    "model": response.model,
                    "confidence": response.confidence_score,
                    "execution_time": response.execution_time_seconds
                }
            }
        except json.JSONDecodeError:
            # Fallback if AI doesn't return valid JSON
            return {
                "vision_spec": {
                    "project_name": project_name,
                    "core_vision": vision_input,
                    "success_criteria": ["System functions as intended", "Users adopt the solution"],
                    "non_negotiables": ["Data security", "User privacy"],
                    "target_timeline": "30 days",
                    "emotional_tone": "professional",
                    "technical_constraints": ["web-based", "responsive design"]
                },
                "ai_metadata": {
                    "provider": response.provider.value,
                    "model": response.model,
                    "confidence": 0.5,  # Lower confidence due to parsing failure
                    "execution_time": response.execution_time_seconds,
