class EnhancedTechnicalArchitectAgent:
    def __init__(self, ai_coordinator: AICoordinator):
        self.ai_coordinator = ai_coordinator

    async def design_architecture(self, vision_spec: Dict, requirements: Dict = None) -> Dict:
        """Design technical architecture using AI"""
        request = AIRequest(
            task_type=TaskType.ARCHITECTURE_DESIGN,
            prompt=f"Design technical architecture for: {vision_spec.get('core_vision', '')}",
            context={
                "vision_spec": vision_spec,
                "requirements": requirements or {},
                "architecture_patterns": ["microservices", "monolith", "serverless", "jamstack"],
                "technology_stack_options": {
                    "frontend": ["React", "Vue", "Angular", "Svelte"],
                    "backend": ["Node.js", "Python/FastAPI", "Go", "Rust"],
                    "database": ["PostgreSQL", "MongoDB", "Redis", "SQLite"],
                    "deployment": ["Docker", "Kubernetes", "Serverless", "VPS"]
                },
                "non_functional_requirements": {
                    "performance": vision_spec.get("technical_constraints", {}).get("performance", "standard"),
                    "scalability": "horizontal",
                    "availability": "99.9%",
                    "security": "standard"
                }
            },
            temperature=0.5,  # Lower temperature for more consistent technical decisions
            max_tokens=3000
        )

        response = await self.ai_coordinator.process_request(request)

        return {
            "architecture": self._parse_architecture_response(response.content),
            "ai_metadata": {
                "provider": response.provider.value,
                "model": response.model,
                "confidence": response.confidence_score,
                "execution_time": response.execution_time_seconds
            }
        }

    def _parse_architecture_response(self, content: str) -> Dict:
        """Parse and validate architecture response"""
        try:
            architecture = json.loads(content)

            # Validate required sections
            required_sections = [
                "technology_stack", "database_schema", "api_design", 
                "security_architecture", "deployment_strategy"
            ]

            for section in required_sections:
                if section not in architecture:
                    architecture[section] = f"TODO: Define {section}"

            return architecture

        except json.JSONDecodeError:
            # Fallback architecture
            return {
                "technology_stack": {
                    "frontend": "React + TypeScript",
                    "backend": "Node.js + Express",
                    "database": "PostgreSQL",
                    "caching": "Redis",
                    "queue": "Redis Queue"
                },
                "database_schema": {"users": ["id", "email", "created_at"]},
                "api_design": {"base_url": "/api/v1", "auth": "JWT", "rate_limiting": "100/hour"},
                "security_architecture": ["HTTPS", "Input validation", "CSRF protection"],
                "deployment_strategy": "Docker containers on cloud platform",
                "note": "Fallback architecture used due to parsing error"
            }

