class AIUtilities:
    def __init__(self, ai_coordinator: AICoordinator):
        self.ai_coordinator = ai_coordinator

    async def generate_code(self, specification: str, language: str = "python", context: Dict = None) -> str:
        """Generate code based on specification"""
        request = AIRequest(
            task_type=TaskType.CODE_GENERATION,
            prompt=f"Generate {language} code for: {specification}",
            context={
                "language": language,
                "specification": specification,
                "context": context or {},
                "coding_standards": {
                    "style": "clean_code",
                    "documentation": "comprehensive",
                    "testing": "unit_tests_included",
                    "error_handling": "robust"
                }
            },
            temperature=0.3,  # Low temperature for more consistent code
            max_tokens=4000
        )

        response = await self.ai_coordinator.process_request(request)
        return response.content

    async def evaluate_system(self, system_description: str, original_vision: Dict, context: Dict = None) -> Dict:
        """Evaluate system against original vision"""
        request = AIRequest(
            task_type=TaskType.SYSTEM_EVALUATION,
            prompt=f"Evaluate this system: {system_description}",
            context={
                "original_vision": original_vision,
                "system_description": system_description,
                "evaluation_criteria": [
                    "vision_alignment",
                    "technical_quality",
                    "user_experience",
                    "performance",
                    "security",
                    "maintainability"
                ],
                "context": context or {}
            },
            temperature=0.4,
            max_tokens=2000
        )

        response = await self.ai_coordinator.process_request(request)

        try:
            evaluation = json.loads(response.content)
            return evaluation
        except json.JSONDecodeError:
            return {
                "vision_alignment_score": 75,
                "technical_quality": 80,
                "recommendations": ["Improve documentation", "Add more tests"],
                "needs_escalation": False,
                "note": "Fallback evaluation due to parsing error"
            }

    async def suggest_improvements(self, current_system: Dict, performance_metrics: Dict = None) -> List[str]:
        """Suggest system improvements based on current state and metrics"""
        request = AIRequest(
            task_type=TaskType.SYSTEM_EVALUATION,
            prompt="Suggest improvements for the current system",
            context={
                "current_system": current_system,
                "performance_metrics": performance_metrics or {},
                "improvement_areas": [
                    "performance", "security", "user_experience", 
                    "maintainability", "scalability", "cost_optimization"
                ]
            },
            temperature=0.6,
            max_tokens=1500
        )

        response = await self.ai_coordinator.process_request(request)

        # Extract suggestions from response
        try:
            suggestions = json.loads(response.content)
            return suggestions.get("suggestions", [])
        except:
            # Fallback: extract bullet points or numbered lists
            lines = response.content.split('\n')
            suggestions = []
            for line in lines:
                line = line.strip()
                if line.startswith(('-', '•', '*')) or (line and line[0].isdigit() and '.' in line):
                    suggestions.append(line.lstrip('-•* ').split('.', 1)[-1].strip())

            return suggestions[:10]  # Limit to top 10 suggestions

