def load_ai_config() -> Dict[str, str]:
    """Load AI configuration from environment or config file"""
    config = {}

    # Try environment variables first
    env_keys = ["OPENAI_API_KEY", "ANTHROPIC_API_KEY", "LOCAL_AI_URL"]
    for key in env_keys:
        value = os.environ.get(key)
        if value:
            config[key] = value

    # Try loading from .env file
    try:
        from dotenv import load_dotenv
        load_dotenv()
        for key in env_keys:
            value = os.environ.get(key)
            if value and key not in config:
                config[key] = value
    except ImportError:
        pass

    return config

def create_ai_coordinator() -> AICoordinator:
    """Create and initialize AI coordinator"""
    config = load_ai_config()
    coordinator = AICoordinator(config)
    return coordinator

