{
  "name": "universal-note-hub-mcp",
  "version": "1.0.0",
  "description": "MCP server for universal note management",
  "main": "src/index.js",
  "type": "module",
  "scripts": {
    "start": "node src/index.js",
    "dev": "node --watch src/index.js"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^0.5.0",
    "mongodb": "^6.0.0",
    "zod": "^3.22.0"
  },
  "keywords": ["mcp", "notes", "mongodb"],
  "author": "Your Name",
  "license": "MIT"
}

#!/usr/bin/env node

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { CallToolRequestSchema, ListToolsRequestSchema } from '@modelcontextprotocol/sdk/types.js';
import { MongoClient } from 'mongodb';
import { z } from 'zod';

// Validation schemas
const CreateNoteSchema = z.object({
  title: z.string().min(1, "Title is required"),
  content: z.string(),
  tags: z.array(z.string()).optional().default([]),
  category: z.string().optional().default("general")
});

const GetNoteSchema = z.object({
  id: z.string().min(1, "Note ID is required")
});

class UniversalNoteHub {
  constructor() {
    this.server = new Server(
      {
        name: 'universal-note-hub',
        version: '1.0.0',
      },
      {
        capabilities: {
          tools: {},
        },
      }
    );

    this.mongoClient = null;
    this.db = null;
    this.notesCollection = null;

    this.setupToolHandlers();
    this.setupErrorHandling();
  }

  async initialize() {
    try {
      // Connect to MongoDB
      this.mongoClient = new MongoClient('mongodb://localhost:27017');
      await this.mongoClient.connect();
      this.db = this.mongoClient.db('note_hub');
      this.notesCollection = this.db.collection('notes');

      // Create indexes for better search performance
      await this.notesCollection.createIndex({ title: 'text', content: 'text' });
      await this.notesCollection.createIndex({ tags: 1 });
      await this.notesCollection.createIndex({ createdAt: -1 });

      console.log('Connected to MongoDB successfully');
    } catch (error) {
      console.error('Failed to connect to MongoDB:', error);
      process.exit(1);
    }
  }

  setupToolHandlers() {
    // List available tools
    this.server.setRequestHandler(ListToolsRequestSchema, async () => {
      return {
        tools: [
          {
            name: 'create_note',
            description: 'Create a new note in the universal note hub',
            inputSchema: {
              type: 'object',
              properties: {
                title: {
                  type: 'string',
                  description: 'The title of the note',
                },
                content: {
                  type: 'string',
                  description: 'The main content of the note',
                },
                tags: {
                  type: 'array',
                  items: { type: 'string' },
                  description: 'Optional tags for categorization',
                },
                category: {
                  type: 'string',
                  description: 'Optional category (default: general)',
                },
              },
              required: ['title', 'content'],
            },
          },
          {
            name: 'get_note',
            description: 'Retrieve a note by its ID',
            inputSchema: {
              type: 'object',
              properties: {
                id: {
                  type: 'string',
                  description: 'The unique ID of the note to retrieve',
                },
              },
              required: ['id'],
            },
          },
        ],
      };
    });

    // Handle tool calls
    this.server.setRequestHandler(CallToolRequestSchema, async (request) => {
      const { name, arguments: args } = request.params;

      try {
        switch (name) {
          case 'create_note':
            return await this.createNote(args);
          case 'get_note':
            return await this.getNote(args);
          default:
            throw new Error(`Unknown tool: ${name}`);
        }
      } catch (error) {
        return {
          content: [
            {
              type: 'text',
              text: `Error: ${error.message}`,
            },
          ],
        };
      }
    });
  }

  async createNote(args) {
    // Validate input
    const validatedArgs = CreateNoteSchema.parse(args);

    const note = {
      ...validatedArgs,
      createdAt: new Date(),
      updatedAt: new Date(),
      wordCount: this.countWords(validatedArgs.content),
    };

    const result = await this.notesCollection.insertOne(note);

    return {
      content: [
        {
          type: 'text',
          text: `Note created successfully!\n\nID: ${result.insertedId}\nTitle: ${note.title}\nCategory: ${note.category}\nTags: ${note.tags.join(', ') || 'none'}\nWord Count: ${note.wordCount}\nCreated: ${note.createdAt.toISOString()}`,
        },
      ],
    };
  }

  async getNote(args) {
    // Validate input
    const validatedArgs = GetNoteSchema.parse(args);

    const { ObjectId } = await import('mongodb');
    let noteId;

    try {
      noteId = new ObjectId(validatedArgs.id);
    } catch (error) {
      throw new Error('Invalid note ID format');
    }

    const note = await this.notesCollection.findOne({ _id: noteId });

    if (!note) {
      throw new Error('Note not found');
    }

    return {
      content: [
        {
          type: 'text',
          text: `# ${note.title}\n\n**Category:** ${note.category}\n**Tags:** ${note.tags.join(', ') || 'none'}\n**Created:** ${note.createdAt.toISOString()}\n**Updated:** ${note.updatedAt.toISOString()}\n**Word Count:** ${note.wordCount}\n\n---\n\n${note.content}`,
        },
      ],
    };
  }

  countWords(text) {
    return text.trim().split(/\s+/).filter(word => word.length > 0).length;
  }

  setupErrorHandling() {
    this.server.onerror = (error) => {
      console.error('[MCP Error]', error);
    };

    process.on('SIGINT', async () => {
      await this.cleanup();
      process.exit(0);
    });
  }

  async cleanup() {
    if (this.mongoClient) {
      await this.mongoClient.close();
      console.log('MongoDB connection closed');
    }
  }

  async run() {
    const transport = new StdioServerTransport();
    await this.server.connect(transport);
    console.log('Universal Note Hub MCP server running on stdio');
  }
}

// Start the server
const noteHub = new UniversalNoteHub();
await noteHub.initialize();
await noteHub.run();

