    try {
      noteId = new ObjectId(validatedArgs.id);
    } catch (error) {
      throw new Error('Invalid note ID format');
    }

    const note = await this.notesCollection.findOne({ _id: noteId });

    if (!note) {
      throw new Error('Note not found');
    }

    return {
      content: [
        {
          type: 'text',
          text: `# ${note.title}\n\n**Category:** ${note.category}\n**Tags:** ${note.tags.join(', ') || 'none'}\n**Created:** ${note.createdAt.toISOString()}\n**Updated:** ${note.updatedAt.toISOString()}\n**Word Count:** ${note.wordCount}\n\n---\n\n${note.content}`,
        },
      ],
    };
  }

  async listNotes(args) {
    const validatedArgs = ListNotesSchema.parse(args);

    const filter = {};
    if (validatedArgs.category) {
      filter.category = validatedArgs.category;
    }
    if (validatedArgs.tags && validatedArgs.tags.length > 0) {
      filter.tags = { $all: validatedArgs.tags };
    }

    const sort = {};
    sort[validatedArgs.sortBy] = validatedArgs.sortOrder === 'asc' ? 1 : -1;

    const totalCount = await this.notesCollection.countDocuments(filter);

    const notes = await this.notesCollection
      .find(filter)
      .sort(sort)
      .skip(validatedArgs.skip)
      .limit(validatedArgs.limit)
      .toArray();

    const hasMore = (validatedArgs.skip + validatedArgs.limit) < totalCount;
    const currentPage = Math.floor(validatedArgs.skip / validatedArgs.limit) + 1;
    const totalPages = Math.ceil(totalCount / validatedArgs.limit);

    if (notes.length === 0) {
      return {
        content: [
          {
            type: 'text',
            text: `No notes found${validatedArgs.category ? ` in category "${validatedArgs.category}"` : ''}${validatedArgs.tags?.length > 0 ? ` with tags: ${validatedArgs.tags.join(', ')}` : ''}.`,
          },
        ],
      };
    }

    const notesList = notes.map(note => {
      const preview = note.content.length > 100 
        ? note.content.substring(0, 100) + '...' 
        : note.content;

      return `**${note.title}** (ID: ${note._id})\n📁 ${note.category} | 🏷️ ${note.tags.join(', ') || 'none'} | 📝 ${note.wordCount} words\n📅 ${note.createdAt.toLocaleDateString()} | ${preview}`;
    }).join('\n\n---\n\n');

    const paginationInfo = `\n\n**Pagination Info:**\n📊 Showing ${validatedArgs.skip + 1}-${Math.min(validatedArgs.skip + validatedArgs.limit, totalCount)} of ${totalCount} notes\n📄 Page ${currentPage} of ${totalPages}${hasMore ? ' | More available' : ' | Last page'}`;

    const filterInfo = validatedArgs.category || validatedArgs.tags?.length > 0 
      ? `\n**Filters Applied:** ${validatedArgs.category ? `Category: ${validatedArgs.category}` : ''}${validatedArgs.tags?.length > 0 ? ` Tags: ${validatedArgs.tags.join(', ')}` : ''}\n`
      : '';

    return {
      content: [
        {
          type: 'text',
          text: `# 📚 Your Notes\n${filterInfo}\n${notesList}${paginationInfo}`,
        },
      ],
    };
  }

  countWords(text) {
    return text.trim().split(/\s+/).filter(word => word.length > 0).length;
  }

  setupErrorHandling() {
    this.server.onerror = (error) => {
      console.error('[MCP Error]', error);
    };

    process.on('SIGINT', async () => {
      await this.cleanup();
      process.exit(0);
    });
  }

  async cleanup() {
    if (this.mongoClient) {
      await this.mongoClient.close();
      console.log('MongoDB connection closed');
    }
  }

  async run() {
    const transport = new StdioServerTransport();
    await this.server.connect(transport);
    console.log('Universal Note Hub MCP server running on stdio');
  }
}

