async updateNote(args) {
  const validatedArgs = UpdateNoteSchema.parse(args);

  const { ObjectId } = await import('mongodb');
  let noteId;

  try {
    noteId = new ObjectId(validatedArgs.id);
  } catch (error) {
    throw new Error('Invalid note ID format');
  }

  // Check if note exists
  const existingNote = await this.notesCollection.findOne({ _id: noteId });
  if (!existingNote) {
    throw new Error('Note not found');
  }

  // Build update object with only provided fields
  const updateFields = {
    updatedAt: new Date()
  };

  if (validatedArgs.title !== undefined) {
    updateFields.title = validatedArgs.title;
  }
  if (validatedArgs.content !== undefined) {
    updateFields.content = validatedArgs.content;
    updateFields.wordCount = this.countWords(validatedArgs.content);
  }
  if (validatedArgs.tags !== undefined) {
    updateFields.tags = validatedArgs.tags;
  }
  if (validatedArgs.category !== undefined) {
    updateFields.category = validatedArgs.category;
  }

  // Update the note
  const result = await this.notesCollection.updateOne(
    { _id: noteId },
    { $set: updateFields }
  );

  if (result.matchedCount === 0) {
    throw new Error('Note not found');
  }

  // Get the updated note to show changes
  const updatedNote = await this.notesCollection.findOne({ _id: noteId });

  const changedFields = Object.keys(updateFields).filter(key => key !== 'updatedAt');

  return {
    content: [
      {
        type: 'text',
        text: `Note updated successfully!\n\nID: ${updatedNote._id}\nTitle: ${updatedNote.title}\nCategory: ${updatedNote.category}\nTags: ${updatedNote.tags.join(', ') || 'none'}\nWord Count: ${updatedNote.wordCount}\nUpdated: ${updatedNote.updatedAt.toISOString()}\n\nFields changed: ${changedFields.join(', ')}`,
      },
    ],
  };
}

async deleteNote(args) {
  const validatedArgs = DeleteNoteSchema.parse(args);

  const { ObjectId } = await import('mongodb');
  let noteId;

  try {
    noteId = new ObjectId(validatedArgs.id);
  } catch (error) {
    throw new Error('Invalid note ID format');
  }

  // Get note details before deletion for confirmation
  const noteToDelete = await this.notesCollection.findOne({ _id: noteId });
  if (!noteToDelete) {
    throw new Error('Note not found');
  }

  // Delete the note
  const result = await this.notesCollection.deleteOne({ _id: noteId });

  if (result.deletedCount === 0) {
    throw new Error('Note not found or could not be deleted');
  }

  return {
    content: [
      {
        type: 'text',
        text: `Note deleted successfully!\n\nDeleted note details:\nID: ${noteToDelete._id}\nTitle: "${noteToDelete.title}"\nCategory: ${noteToDelete.category}\nTags: ${noteToDelete.tags.join(', ') || 'none'}\nWord Count: ${noteToDelete.wordCount}\nCreated: ${noteToDelete.createdAt.toISOString()}\n\n⚠️ This action cannot be undone.`,
      },
    ],
  };
}

