import { z } from 'zod';

export const CreateNoteSchema = z.object({
  title: z.string().min(1, "Title is required"),
  content: z.string(),
  tags: z.array(z.string()).optional().default([]),
  category: z.string().optional().default("general")
});

export const GetNoteSchema = z.object({
  id: z.string().min(1, "Note ID is required")
});

export const ListNotesSchema = z.object({
  limit: z.number().min(1).max(100).optional().default(10),
  skip: z.number().min(0).optional().default(0),
  category: z.string().optional(),
  tags: z.array(z.string()).optional(),
  sortBy: z.enum(['createdAt', 'updatedAt', 'title', 'wordCount']).optional().default('createdAt'),
  sortOrder: z.enum(['asc', 'desc']).optional().default('desc')
});

export const UpdateNoteSchema = z.object({
  id: z.string().min(1, "Note ID is required"),
  title: z.string().min(1).optional(),
  content: z.string().optional(),
  tags: z.array(z.string()).optional(),
  category: z.string().optional()
});

export const DeleteNoteSchema = z.object({
  id: z.string().min(1, "Note ID is required")
});

/**
 * Count words in a text string
 * @param {string} text - The text to count words in
 * @returns {number} Word count
 */
export function countWords(text) {
  return text.trim().split(/\s+/).filter(word => word.length > 0).length;
}

/**
 * Create a MongoDB ObjectId from string
 * @param {string} id - The ID string
 * @returns {ObjectId} MongoDB ObjectId
 * @throws {Error} If ID format is invalid
 */
export async function createObjectId(id) {
  const { ObjectId } = await import('mongodb');
  try {
    return new ObjectId(id);
  } catch (error) {
    throw new Error('Invalid note ID format');
  }
}

/**
 * Format a note preview (truncate long content)
 * @param {string} content - Full note content
 * @param {number} maxLength - Maximum preview length (default: 100)
 * @returns {string} Formatted preview
 */
export function formatPreview(content, maxLength = 100) {
  return content.length > maxLength 
    ? content.substring(0, maxLength) + '...' 
    : content;
}

import { MongoClient } from 'mongodb';

class DatabaseConnection {
  constructor(connectionString = 'mongodb://localhost:27017', dbName = 'note_hub') {
    this.connectionString = connectionString;
    this.dbName = dbName;
    this.client = null;
    this.db = null;
    this.notesCollection = null;
  }

  async connect() {
    try {
      this.client = new MongoClient(this.connectionString);
      await this.client.connect();
      this.db = this.client.db(this.dbName);
      this.notesCollection = this.db.collection('notes');

      // Create indexes for better performance
      await this.createIndexes();

      console.log('Connected to MongoDB successfully');
      return this;
    } catch (error) {
      console.error('Failed to connect to MongoDB:', error);
      throw error;
    }
  }

  async createIndexes() {
    await this.notesCollection.createIndex({ title: 'text', content: 'text' });
    await this.notesCollection.createIndex({ tags: 1 });
    await this.notesCollection.createIndex({ createdAt: -1 });
    await this.notesCollection.createIndex({ category: 1 });
  }

  async close() {
    if (this.client) {
      await this.client.close();
      console.log('MongoDB connection closed');
    }
  }

  getCollection() {
    if (!this.notesCollection) {
      throw new Error('Database not connected. Call connect() first.');
    }
    return this.notesCollection;
  }
}

// Export singleton instance
export const database = new DatabaseConnection();
export default database;

import { CreateNoteSchema } from '../schemas/validation.js';
import { countWords } from '../utils/helpers.js';
import database from '../database/connection.js';

export const createNoteDefinition = {
  name: "create_note",
  description: "Create a new note in the universal note hub",
  inputSchema: {
    type: "object",
    properties: {
      title: {
        type: "string",
        description: "The title of the note"
      },
      content: {
        type: "string", 
        description: "The main content of the note"
      },
      tags: {
        type: "array",
        items: { type: "string" },
        description: "Optional tags for categorization"
      },
      category: {
        type: "string",
        description: "Optional category (default: general)"
      }
    },
    required: ["title", "content"]
  }
};

export async function createNote(args) {
  const validatedArgs = CreateNoteSchema.parse(args);

  const note = {
    ...validatedArgs,
    createdAt: new Date(),
    updatedAt: new Date(),
    wordCount: countWords(validatedArgs.content),
  };

  const collection = database.getCollection();
  const result = await collection.insertOne(note);

  return {
    content: [
      {
        type: 'text',
        text: `Note created successfully!\n\nID: ${result.insertedId}\nTitle: ${note.title}\nCategory: ${note.category}\nTags: ${note.tags.join(', ') || 'none'}\nWord Count: ${note.wordCount}\nCreated: ${note.createdAt.toISOString()}`,
      },
    ],
  };
}

import { GetNoteSchema } from '../schemas/validation.js';
import { createObjectId } from '../utils/helpers.js';
import database from '../database/connection.js';

export const getNoteDefinition = {
  name: "get_note",
  description: "Retrieve a note by its ID", 
  inputSchema: {
    type: "object",
    properties: {
      id: {
        type: "string",
        description: "The unique ID of the note to retrieve"
      }
    },
    required: ["id"]
  }
};

export async function getNote(args) {
  const validatedArgs = GetNoteSchema.parse(args);
  const noteId = await createObjectId(validatedArgs.id);

  const collection = database.getCollection();
  const note = await collection.findOne({ _id: noteId });

  if (!note) {
    throw new Error('Note not found');
  }

  return {
    content: [
      {
        type: 'text',
        text: `# ${note.title}\n\n**Category:** ${note.category}\n**Tags:** ${note.tags.join(', ') || 'none'}\n**Created:** ${note.createdAt.toISOString()}\n**Updated:** ${note.updatedAt.toISOString()}\n**Word Count:** ${note.wordCount}\n\n---\n\n${note.content}`,
      },
    ],
  };
}

import { ListNotesSchema } from '../schemas/validation.js';
import { formatPreview } from '../utils/helpers.js';
import database from '../database/connection.js';

export const listNotesDefinition = {
  name: "list_notes",
  description: "List notes with optional filtering, sorting, and pagination",
  inputSchema: {
    type: "object",
    properties: {
      limit: {
        type: "number",
        description: "Number of notes to return (1-100, default: 10)",
        minimum: 1,
        maximum: 100
      },
      skip: {
        type: "number", 
        description: "Number of notes to skip for pagination (default: 0)",
        minimum: 0
      },
      category: {
        type: "string",
        description: "Filter by category"
      },
      tags: {
        type: "array",
        items: { type: "string" },
        description: "Filter by tags (notes must have ALL specified tags)"
      },
      sortBy: {
        type: "string",
        enum: ["createdAt", "updatedAt", "title", "wordCount"],
        description: "Field to sort by (default: createdAt)"
      },
      sortOrder: {
        type: "string",
        enum: ["asc", "desc"],
        description: "Sort order (default: desc)"
      }
    },
    required: []
  }
};

export async function listNotes(args) {
  const validatedArgs = ListNotesSchema.parse(args);

  // Build filter query
  const filter = {};
  if (validatedArgs.category) {
    filter.category = validatedArgs.category;
  }
  if (validatedArgs.tags && validatedArgs.tags.length > 0) {
    filter.tags = { $all: validatedArgs.tags };
  }

  // Build sort query
  const sort = {};
  sort[validatedArgs.sortBy] = validatedArgs.sortOrder === 'asc' ? 1 : -1;

  const collection = database.getCollection();

  // Get total count for pagination info
  const totalCount = await collection.countDocuments(filter);

  // Get notes with pagination
  const notes = await collection
    .find(filter)
    .sort(sort)
    .skip(validatedArgs.skip)
    .limit(validatedArgs.limit)
    .toArray();

  // Calculate pagination info
  const hasMore = (validatedArgs.skip + validatedArgs.limit) < totalCount;
  const currentPage = Math.floor(validatedArgs.skip / validatedArgs.limit) + 1;
  const totalPages = Math.ceil(totalCount / validatedArgs.limit);

  // Format response
  if (notes.length === 0) {
    return {
      content: [
        {
          type: 'text',
          text: `No notes found${validatedArgs.category ? ` in category "${validatedArgs.category}"` : ''}${validatedArgs.tags?.length > 0 ? ` with tags: ${validatedArgs.tags.join(', ')}` : ''}.`,
        },
      ],
    };
  }

  // Create note list
  const notesList = notes.map(note => {
    const preview = formatPreview(note.content);

    return `**${note.title}** (ID: ${note._id})\n📁 ${note.category} | 🏷️ ${note.tags.join(', ') || 'none'} | 📝 ${note.wordCount} words\n📅 ${note.createdAt.toLocaleDateString()} | ${preview}`;
  }).join('\n\n---\n\n');

  const paginationInfo = `\n\n**Pagination Info:**\n📊 Showing ${validatedArgs.skip + 1}-${Math.min(validatedArgs.skip + validatedArgs.limit, totalCount)} of ${totalCount} notes\n📄 Page ${currentPage} of ${totalPages}${hasMore ? ' | More available' : ' | Last page'}`;

  const filterInfo = validatedArgs.category || validatedArgs.tags?.length > 0 
    ? `\n**Filters Applied:** ${validatedArgs.category ? `Category: ${validatedArgs.category}` : ''}${validatedArgs.tags?.length > 0 ? ` Tags: ${validatedArgs.tags.join(', ')}` : ''}\n`
    : '';

  return {
    content: [
      {
        type: 'text',
        text: `# 📚 Your Notes\n${filterInfo}\n${notesList}${paginationInfo}`,
      },
    ],
  };
}

import { UpdateNoteSchema } from '../schemas/validation.js';
import { createObjectId, countWords } from '../utils/helpers.js';
import database from '../database/connection.js';

export const updateNoteDefinition = {
  name: "update_note",
  description: "Update an existing note by its ID",
  inputSchema: {
    type: "object",
    properties: {
      id: {
        type: "string",
        description: "The unique ID of the note to update"
      },
      title: {
        type: "string",
        description: "New title for the note (optional)"
      },
      content: {
        type: "string",
        description: "New content for the note (optional)"
      },
      tags: {
        type: "array",
        items: { type: "string" },
        description: "New tags for the note (optional, replaces existing tags)"
      },
      category: {
        type: "string",
        description: "New category for the note (optional)"
      }
    },
    required: ["id"]
  }
};

export async function updateNote(args) {
  const validatedArgs = UpdateNoteSchema.parse(args);
  const noteId = await createObjectId(validatedArgs.id);

  const collection = database.getCollection();

  // Check if note exists
  const existingNote = await collection.findOne({ _id: noteId });
  if (!existingNote) {
    throw new Error('Note not found');
  }

  // Build update object with only provided fields
  const updateFields = {
    updatedAt: new Date()
  };

  if (validatedArgs.title !== undefined) {
    updateFields.title = validatedArgs.title;
  }
  if (validatedArgs.content !== undefined) {
    updateFields.content = validatedArgs.content;
    updateFields.wordCount = countWords(validatedArgs.content);
  }
  if (validatedArgs.tags !== undefined) {
    updateFields.tags = validatedArgs.tags;
  }
  if (validatedArgs.category !== undefined) {
    updateFields.category = validatedArgs.category;
  }

  // Update the note
  const result = await collection.updateOne(
    { _id: noteId },
    { $set: updateFields }
  );

  if (result.matchedCount === 0) {
    throw new Error('Note not found');
  }

  // Get the updated note to show changes
  const updatedNote = await collection.findOne({ _id: noteId });

  const changedFields = Object.keys(updateFields).filter(key => key !== 'updatedAt');

  return {
    content: [
      {
        type: 'text',
        text: `Note updated successfully!\n\nID: ${updatedNote._id}\nTitle: ${updatedNote.title}\nCategory: ${updatedNote.category}\nTags: ${updatedNote.tags.join(', ') || 'none'}\nWord Count: ${updatedNote.wordCount}\nUpdated: ${updatedNote.updatedAt.toISOString()}\n\nFields changed: ${changedFields.join(', ')}`,
      },
    ],
  };
}

import { DeleteNoteSchema } from '../schemas/validation.js';
import { createObjectId } from '../utils/helpers.js';
import database from '../database/connection.js';

export const deleteNoteDefinition = {
  name: "delete_note",
  description: "Delete a note by its ID (permanent action)",
  inputSchema: {
    type: "object",
    properties: {
      id: {
        type: "string",
        description: "The unique ID of the note to delete"
      }
    },
    required: ["id"]
  }
};

export async function deleteNote(args) {
  const validatedArgs = DeleteNoteSchema.parse(args);
  const noteId = await createObjectId(validatedArgs.id);

  const collection = database.getCollection();

  // Get note details before deletion for confirmation
  const noteToDelete = await collection.findOne({ _id: noteId });
  if (!noteToDelete) {
    throw new Error('Note not found');
  }

  // Delete the note
  const result = await collection.deleteOne({ _id: noteId });

  if (result.deletedCount === 0) {
    throw new Error('Note not found or could not be deleted');
  }

  return {
    content: [
      {
        type: 'text',
        text: `Note deleted successfully!\n\nDeleted note details:\nID: ${noteToDelete._id}\nTitle: "${noteToDelete.title}"\nCategory: ${noteToDelete.category}\nTags: ${noteToDelete.tags.join(', ') || 'none'}\nWord Count: ${noteToDelete.wordCount}\nCreated: ${noteToDelete.createdAt.toISOString()}\n\n⚠️ This action cannot be undone.`,
      },
    ],
  };
}

